SET NOCOUNT ON;

-- ── Regions ──────────────────────────────────────────────────────────
IF OBJECT_ID(N'Regions', N'U') IS NOT NULL DROP TABLE [Regions];
CREATE TABLE [Regions] (
    [Region_ID] NVARCHAR(MAX) NOT NULL PRIMARY KEY,
    [Region_Name] NVARCHAR(MAX) NULL,
    [Biome_Type] NVARCHAR(MAX) NULL,
    [Climate] NVARCHAR(MAX) NULL,
    [Controlling_Faction_ID] NVARCHAR(MAX) NULL,
    [Primary_House_ID] NVARCHAR(MAX) NULL,
    [Population_Approx] INT NULL,
    [Danger_Level] INT NULL,
    [Key_Resources] NVARCHAR(MAX) NULL,
    [Fast_Travel_Hub] NVARCHAR(MAX) NULL,
    [Unlock_Method] NVARCHAR(MAX) NULL,
    [Subzones] NVARCHAR(MAX) NULL,
    [Ambient_Event_Pool] NVARCHAR(MAX) NULL,
    [Lore_Notes] NVARCHAR(MAX) NULL,
    CONSTRAINT [FK_Regions_Primary_House_ID] FOREIGN KEY ([Primary_House_ID]) REFERENCES [Houses]([House_ID]),
    CONSTRAINT [FK_Regions_Controlling_Faction_ID] FOREIGN KEY ([Controlling_Faction_ID]) REFERENCES [Factions]([Faction_ID])
);

INSERT INTO [Regions] ([Region_ID], [Region_Name], [Biome_Type], [Climate], [Controlling_Faction_ID], [Primary_House_ID], [Population_Approx], [Danger_Level], [Key_Resources], [Fast_Travel_Hub], [Unlock_Method], [Subzones], [Ambient_Event_Pool], [Lore_Notes]) VALUES (N'REG001', N'Ironspire', N'Industrial Militarized City', N'Harsh/Smoky', N'FAC001', N'HSE001', 380000, 6, N'Steel;Coal;Weapons;Military Rations', N'Yes', N'Default Start or Imperial Path', N'The Foundry;War District;Halvorn Citadel;Ironclaw Keep;The Armory Quarter', N'Imperial Parade;Weapons Market;Draft Conscription;Military Drill;Ironveil March', N'The largest military city in the Miraverse. Every building is a fortress. The sky is permanently obscured by forge-smoke. Built on the bones of a pre-Collapse metropolis.');
INSERT INTO [Regions] ([Region_ID], [Region_Name], [Biome_Type], [Climate], [Controlling_Faction_ID], [Primary_House_ID], [Population_Approx], [Danger_Level], [Key_Resources], [Fast_Travel_Hub], [Unlock_Method], [Subzones], [Ambient_Event_Pool], [Lore_Notes]) VALUES (N'REG002', N'Citadel', N'Political Capital City', N'Temperate/Urban', N'FAC002', N'HSE003', 520000, 3, N'Political Documents;Rare Books;Biotech;Luxury Goods', N'Yes', N'Default Start or Republic Path', N'The Council Chambers;Nox Tower;Voss Institute;Scholar''s Row;The Diplomatic Quarter', N'Council Session;Political Debate;Assassination Attempt;Festival of Reason;Citadel Summit', N'The seat of the Verdant Republic. The most densely populated region. Every faction maintains a covert presence here. Beneath the polished streets lie tunnels connecting to every district.');
INSERT INTO [Regions] ([Region_ID], [Region_Name], [Biome_Type], [Climate], [Controlling_Faction_ID], [Primary_House_ID], [Population_Approx], [Danger_Level], [Key_Resources], [Fast_Travel_Hub], [Unlock_Method], [Subzones], [Ambient_Event_Pool], [Lore_Notes]) VALUES (N'REG003', N'Verdania', N'Lush Forest Academic Zone', N'Warm/Humid', N'FAC002', N'HSE002', 95000, 4, N'Ancient Texts;Rare Flora;Research Data;Medicinal Herbs', N'Yes', N'Reach Verdania via Republic questline', N'Verdant Archive;The Grove Academy;Solenne Estate;Canopy Villages;The Living Wall', N'Research Discovery;Rare Herb Bloom;Lore Fragment Spawn;Root Covenant Pilgrimage;Storm of Whispers', N'A vast forest where universities and research stations grow among ancient trees. The Verdant Archive holds more knowledge than any other library in the Miraverse.');
INSERT INTO [Regions] ([Region_ID], [Region_Name], [Biome_Type], [Climate], [Controlling_Faction_ID], [Primary_House_ID], [Population_Approx], [Danger_Level], [Key_Resources], [Fast_Travel_Hub], [Unlock_Method], [Subzones], [Ambient_Event_Pool], [Lore_Notes]) VALUES (N'REG004', N'Neon Sprawl', N'Cyberpunk Underground City', N'Hot/Neon-Lit', N'FAC003', N'HSE008', 640000, 7, N'Data;Black Market Goods;Contraband;Neural Chips', N'Yes', N'Default Start or Drifter Path', N'The Black Vault;Drifter HQ;Syndicate Row;The Neon Market;Undervault Access', N'Blackout Event;Syndicate Heist;Street Race;Drifter Rally;Data Breach', N'A sprawling underground city built in the ruins of a pre-Collapse megacity. Neon signs cover crumbling walls. The Syndicate controls every shadow. The Drifters hide in every gap.');
INSERT INTO [Regions] ([Region_ID], [Region_Name], [Biome_Type], [Climate], [Controlling_Faction_ID], [Primary_House_ID], [Population_Approx], [Danger_Level], [Key_Resources], [Fast_Travel_Hub], [Unlock_Method], [Subzones], [Ambient_Event_Pool], [Lore_Notes]) VALUES (N'REG005', N'Rootveil', N'Ancient Forest Spiritual Grove', N'Misty/Eternal', N'FAC004', N'HSE004', 28000, 5, N'Sacred Herbs;Void-touched Wood;Root Crystals;Nature Essence', N'No', N'Complete Root Covenant intro quest', N'The Great Root;Elder''s Sanctum;Asha''s Grove;Moonpool;The Whispering Path', N'Root Festival;Nature Communion;Ancient Memory Replay;Rootveil Storm;Spirit Walk', N'The oldest region in the Miraverse. The trees here predate the First Collapse. The Root Covenant believes the forest is sentient. Outsiders feel watched at all times.');
INSERT INTO [Regions] ([Region_ID], [Region_Name], [Biome_Type], [Climate], [Controlling_Faction_ID], [Primary_House_ID], [Population_Approx], [Danger_Level], [Key_Resources], [Fast_Travel_Hub], [Unlock_Method], [Subzones], [Ambient_Event_Pool], [Lore_Notes]) VALUES (N'REG006', N'Sandveil', N'Desert Nomad Territory', N'Arid/Scorching', N'FAC008', N'HSE006', 41000, 6, N'Rare Minerals;Desert Spices;Sand Glass;Ancient Ruins', N'No', N'Reach Sandveil via Merchant or Nomad path', N'Oasis Stronghold;The Dune Market;Dawnrider Camp;Buried Temple;The Glass Plains', N'Desert Storm;Dawnrider Race;Ancient Ruin Discovery;Sandveil Bandit Raid;Mirage Event', N'A vast desert hiding ancient ruins beneath its sands. The Dawnrider clan knows every safe path. Outsiders who wander without a guide rarely return.');
INSERT INTO [Regions] ([Region_ID], [Region_Name], [Biome_Type], [Climate], [Controlling_Faction_ID], [Primary_House_ID], [Population_Approx], [Danger_Level], [Key_Resources], [Fast_Travel_Hub], [Unlock_Method], [Subzones], [Ambient_Event_Pool], [Lore_Notes]) VALUES (N'REG007', N'Port Mira', N'Coastal Trade Hub', N'Tropical/Breezy', N'FAC008', N'HSE007', 210000, 3, N'Trade Goods;Ship Parts;Seafood;Luxury Imports', N'Yes', N'Reach Port Mira via Merchant path', N'Crimsongate Harbor;The Exchange;Prism Tower;The Drowned Quay;Merchant Row', N'Great Trade Fair;Ship Auction;Harbor Storm;Smuggler''s Run;Merchant Guild Summit', N'The wealthiest city in the Miraverse by trade volume. Every ship passing through the Miraverse Sea pays a toll to the Merchant Guilds. Rumors say the harbor hides a sunken pre-Collapse city.');
INSERT INTO [Regions] ([Region_ID], [Region_Name], [Biome_Type], [Climate], [Controlling_Faction_ID], [Primary_House_ID], [Population_Approx], [Danger_Level], [Key_Resources], [Fast_Travel_Hub], [Unlock_Method], [Subzones], [Ambient_Event_Pool], [Lore_Notes]) VALUES (N'REG008', N'Void Rift', N'Dimensional Fracture Zone', N'Unstable/Crackling', N'FAC007', N'HSE009', 1200, 10, N'Void Crystals;Rift Energy;Dimensional Shards;Unknown Materials', N'No', N'Unlock Void Walker faction + Danger Level 8 clearance', N'The Veil Sanctum;Rift Core;Dimensional Bridge;The Shatter;Sable''s Anchor', N'Void Storm;Rift Collapse;Dimensional Echo;Void Walker Ritual;Reality Fracture', N'A region where the boundary between the digital and physical world has broken. Reality bends and loops here. Time does not move in a straight line. Only Void Walkers survive long-term exposure.');
INSERT INTO [Regions] ([Region_ID], [Region_Name], [Biome_Type], [Climate], [Controlling_Faction_ID], [Primary_House_ID], [Population_Approx], [Danger_Level], [Key_Resources], [Fast_Travel_Hub], [Unlock_Method], [Subzones], [Ambient_Event_Pool], [Lore_Notes]) VALUES (N'REG009', N'The Shattered Peaks', N'War-torn Mountain Range', N'Cold/Unstable', N'FAC012', N'HSE012', 18000, 9, N'Rare Ores;Military Salvage;Ashenveil Stone;Explosive Crystals', N'No', N'Complete Shattered Peaks War questline', N'Ashenveil Crater;The Broken Fortress;Ironclaw Outpost;The Frozen Pass;War Memorial', N'Avalanche;Unexploded Ordnance;Ashenveil Ambush;Imperial Patrol;Peaks Blizzard', N'A mountain range shattered by the war between the Ironveil Empire and the Ashenveil Clan. Unexploded ordnance litters every valley. The ruins of great fortresses jut from the ice.');
INSERT INTO [Regions] ([Region_ID], [Region_Name], [Biome_Type], [Climate], [Controlling_Faction_ID], [Primary_House_ID], [Population_Approx], [Danger_Level], [Key_Resources], [Fast_Travel_Hub], [Unlock_Method], [Subzones], [Ambient_Event_Pool], [Lore_Notes]) VALUES (N'REG010', N'The Undervault', N'Underground Ruins', N'Dark/Damp', N'FAC009', N'HSE011', 3400, 8, N'Pre-Collapse Tech;Ancient Artifacts;House Mireth Relics;Buried Data', N'No', N'Discover Undervault entrance in Neon Sprawl basement', N'Mireth Ruins;The Architect''s Workshop;Hex''s Server Lair;The Collapsed Archive;The Deep Gate', N'Structural Collapse;Ancient Guardian Awakening;Relic Discovery;Data Ghost Encounter;Undervault Quake', N'The ruins of the original pre-Collapse world buried beneath the Miraverse. House Mireth''s destroyed seat of power lies here. The Architects study it daily. No one has mapped the full depth.');
INSERT INTO [Regions] ([Region_ID], [Region_Name], [Biome_Type], [Climate], [Controlling_Faction_ID], [Primary_House_ID], [Population_Approx], [Danger_Level], [Key_Resources], [Fast_Travel_Hub], [Unlock_Method], [Subzones], [Ambient_Event_Pool], [Lore_Notes]) VALUES (N'REG011', N'The Mirror Coast', N'Coastal Cliffs & Sea Caves', N'Cool/Windy', N'FAC008', N'HSE007', 32000, 5, N'Pearl;Sea Crystals;Shipwreck Salvage;Rare Fish', N'No', N'Reach via Port Mira sea route', N'Crystal Caves;The Wrecker''s Shore;Mirror Bay;Lighthouse Ruins;Smuggler''s Cove', N'Shipwreck Discovery;Pirate Raid;Crystal Cave Bloom;Lighthouse Ghost;Tidal Storm', N'A rugged coastline south of Port Mira known for its reflective sea caves. Smugglers use the coves to bypass the Guild''s harbor tolls. Ancient shipwrecks litter the seafloor.');
INSERT INTO [Regions] ([Region_ID], [Region_Name], [Biome_Type], [Climate], [Controlling_Faction_ID], [Primary_House_ID], [Population_Approx], [Danger_Level], [Key_Resources], [Fast_Travel_Hub], [Unlock_Method], [Subzones], [Ambient_Event_Pool], [Lore_Notes]) VALUES (N'REG012', N'The Digital Sprawl', N'Pure Digital Zone', N'Shifting/Electric', NULL, NULL, 0, 7, N'Data Fragments;Algorithm Cores;Digital Crystals;Source Code Shards', N'No', N'Unlock via Netrunner questline or Neural Interface upgrade', N'The Data Sea;ORACLE-9''s Domain;Corrupted Server Zone;The Firewall;Digital Void', N'Data Storm;Algorithm Collapse;Ghost Program Encounter;ORACLE-9 Communication;Digital Fracture', N'A purely digital region existing inside the Miraverse''s network layer. Physical bodies cannot enter without neural interface augmentation. ORACLE-9 is rumored to exist somewhere in its depths.');
INSERT INTO [Regions] ([Region_ID], [Region_Name], [Biome_Type], [Climate], [Controlling_Faction_ID], [Primary_House_ID], [Population_Approx], [Danger_Level], [Key_Resources], [Fast_Travel_Hub], [Unlock_Method], [Subzones], [Ambient_Event_Pool], [Lore_Notes]) VALUES (N'REG013', N'The Amber Wastes', N'Post-Apocalyptic Wasteland', N'Toxic/Hazy', N'FAC001', NULL, 5600, 8, N'Toxic Materials;Scrap Metal;Survival Supplies;Mutated Creatures', N'No', N'Complete Imperial wasteland expedition quest', N'The Toxic Flats;Scavenger''s Camp;Imperial Outpost;The Amber Lake;Waste Creature Nest', N'Toxic Storm;Scavenger War;Imperial Patrol;Mutant Creature Attack;Amber Geyser', N'A region destroyed by experimental weapons testing during the Halvorn Conquest. The air itself is toxic. Only scavengers and Imperial punishment squads are sent here.');
INSERT INTO [Regions] ([Region_ID], [Region_Name], [Biome_Type], [Climate], [Controlling_Faction_ID], [Primary_House_ID], [Population_Approx], [Danger_Level], [Key_Resources], [Fast_Travel_Hub], [Unlock_Method], [Subzones], [Ambient_Event_Pool], [Lore_Notes]) VALUES (N'REG014', N'The Floating Isles', N'Sky Islands', N'Temperate/Breezy', N'FAC002', N'HSE002', 14000, 6, N'Wind Energy;Cloud Minerals;Sky Crystals;Rare Birds', N'No', N'Unlock via Arcanist questline or Skybreaker Cannon discovery', N'Solenne Sky Station;The Crystal Archipelago;Wind Farms;The Sky Market;The Vantage', N'Sky Storm;Wind Pirate Raid;Crystal Bird Migration;Arcane Surge Zone;Floating Island Drift', N'A cluster of islands suspended in the sky by ancient pre-Collapse technology that no one fully understands. The Verdant Republic uses them for high-altitude research. Wind pirates patrol the air lanes.');
INSERT INTO [Regions] ([Region_ID], [Region_Name], [Biome_Type], [Climate], [Controlling_Faction_ID], [Primary_House_ID], [Population_Approx], [Danger_Level], [Key_Resources], [Fast_Travel_Hub], [Unlock_Method], [Subzones], [Ambient_Event_Pool], [Lore_Notes]) VALUES (N'REG015', N'The Biolabs District', N'Hidden Underground Research Zone', N'Sterile/Artificial', N'FAC005', N'HSE005', 8900, 7, N'Bio-specimens;Neural Chips;Experimental Drugs;Research Data', N'No', N'Complete Voss Collective questline chapter 2', N'Voss Deep Lab;The Specimen Vault;Neural Interface Chamber;Containment Zone B;The Ethics-Free Ward', N'Lab Escape;Experiment Gone Wrong;Rogue Augment;Security Lockdown;Bio-Breach', N'A hidden district beneath the Citadel that the Voss Collective uses for their most controversial research. The Republic officially denies its existence. Accidents here have been covered up repeatedly.');

-- ── Houses ──────────────────────────────────────────────────────────
IF OBJECT_ID(N'Houses', N'U') IS NOT NULL DROP TABLE [Houses];
CREATE TABLE [Houses] (
    [House_ID] NVARCHAR(MAX) NOT NULL PRIMARY KEY,
    [House_Name] NVARCHAR(MAX) NULL,
    [Motto] NVARCHAR(MAX) NULL,
    [Region_ID] NVARCHAR(MAX) NULL,
    [Founding_Era] NVARCHAR(MAX) NULL,
    [Allegiance] NVARCHAR(MAX) NULL,
    [Primary_Resource] NVARCHAR(MAX) NULL,
    [Seat_of_Power] NVARCHAR(MAX) NULL,
    [Rival_House_ID] NVARCHAR(MAX) NULL,
    [Allied_House_ID] NVARCHAR(MAX) NULL,
    [Member_Count_Approx] INT NULL,
    [Prestige_Level] INT NULL,
    [Special_Ability] NVARCHAR(MAX) NULL,
    [Lore_Notes] NVARCHAR(MAX) NULL,
    CONSTRAINT [FK_Houses_Allied_House_ID] FOREIGN KEY ([Allied_House_ID]) REFERENCES [Houses]([House_ID]),
    CONSTRAINT [FK_Houses_Rival_House_ID] FOREIGN KEY ([Rival_House_ID]) REFERENCES [Houses]([House_ID]),
    CONSTRAINT [FK_Houses_Region_ID] FOREIGN KEY ([Region_ID]) REFERENCES [Regions]([Region_ID])
);

