-- ── Factions ──────────────────────────────────────────────────────────
IF OBJECT_ID(N'Factions', N'U') IS NOT NULL DROP TABLE [Factions];
CREATE TABLE [Factions] (
    [Faction_ID] NVARCHAR(MAX) NOT NULL PRIMARY KEY,
    [Faction_Name] NVARCHAR(MAX) NULL,
    [Faction_Type] NVARCHAR(MAX) NULL,
    [Leader_NPC_ID] NVARCHAR(MAX) NULL,
    [HQ_Region_ID] NVARCHAR(MAX) NULL,
    [Ideology] NVARCHAR(MAX) NULL,
    [Membership_Requirement] NVARCHAR(MAX) NULL,
    [Primary_Goal] NVARCHAR(MAX) NULL,
    [Enemy_Faction_ID] NVARCHAR(MAX) NULL,
    [Allied_Faction_ID] NVARCHAR(MAX) NULL,
    [Reputation_Scale] FLOAT NULL,
    [Member_Perks] NVARCHAR(MAX) NULL,
    [Questline_Count] INT NULL,
    [Lore_Notes] NVARCHAR(MAX) NULL,
    CONSTRAINT [FK_Factions_HQ_Region_ID] FOREIGN KEY ([HQ_Region_ID]) REFERENCES [Regions]([Region_ID]),
    CONSTRAINT [FK_Factions_Leader_NPC_ID] FOREIGN KEY ([Leader_NPC_ID]) REFERENCES [NPCs]([NPC_ID])
);

INSERT INTO [Factions] ([Faction_ID], [Faction_Name], [Faction_Type], [Leader_NPC_ID], [HQ_Region_ID], [Ideology], [Membership_Requirement], [Primary_Goal], [Enemy_Faction_ID], [Allied_Faction_ID], [Reputation_Scale], [Member_Perks], [Questline_Count], [Lore_Notes]) VALUES (N'FAC001', N'The Ironveil Empire', N'Military/Political', N'NPC002', N'REG001', N'Total order through absolute military control. The strong rule; the weak serve.', N'Pass loyalty oath + combat trial', N'Conquer and unify all regions under Imperial law', N'FAC002;FAC006', N'FAC008', NULL, N'Weapon damage +10%;Fast travel to all Imperial zones;Imperial armor set;Halvorn titles', 8, N'Rose from the ruins of the First Collapse. Built Ironspire into the mightiest fortress in the Miraverse. Views the Republic as a threat to stability.');
INSERT INTO [Factions] ([Faction_ID], [Faction_Name], [Faction_Type], [Leader_NPC_ID], [HQ_Region_ID], [Ideology], [Membership_Requirement], [Primary_Goal], [Enemy_Faction_ID], [Allied_Faction_ID], [Reputation_Scale], [Member_Perks], [Questline_Count], [Lore_Notes]) VALUES (N'FAC002', N'The Verdant Republic', N'Academic/Political', N'NPC005', N'REG002', N'Knowledge and democracy as the foundation of civilization. Truth over power.', N'Pass civic knowledge test + sponsor from existing member', N'Establish democratic governance across all regions', N'FAC001;FAC003', N'FAC005', NULL, N'INT +5;Lore unlock speed +20%;Republic safe houses;Exclusive academic questlines', 7, N'Formed by survivors who believed the First Collapse was caused by unchecked power. Built the Citadel as a monument to reason and law.');
INSERT INTO [Factions] ([Faction_ID], [Faction_Name], [Faction_Type], [Leader_NPC_ID], [HQ_Region_ID], [Ideology], [Membership_Requirement], [Primary_Goal], [Enemy_Faction_ID], [Allied_Faction_ID], [Reputation_Scale], [Member_Perks], [Questline_Count], [Lore_Notes]) VALUES (N'FAC003', N'The Obsidian Syndicate', N'Criminal', N'NPC016', N'REG004', N'Profit above all. Loyalty is purchased, never earned. Everyone has a price.', N'Complete initiation heist;Pay 5000 credits', N'Control all black markets and criminal networks across the Miraverse', N'FAC002;FAC007', N'FAC001', NULL, N'Pickpocket skill +25%;Contraband carry limit +50%;Syndicate enforcers as allies;Black Jade questline', 6, N'Emerged in the Neon Sprawl after the Collapse. Built an empire of crime on the digital black market. The true power behind half the Citadel''s decisions.');
INSERT INTO [Factions] ([Faction_ID], [Faction_Name], [Faction_Type], [Leader_NPC_ID], [HQ_Region_ID], [Ideology], [Membership_Requirement], [Primary_Goal], [Enemy_Faction_ID], [Allied_Faction_ID], [Reputation_Scale], [Member_Perks], [Questline_Count], [Lore_Notes]) VALUES (N'FAC004', N'The Root Covenant', N'Religious/Spiritual', N'NPC006', N'REG005', N'The Miraverse is alive. The roots connect all living things. Protect nature at all costs.', N'Complete Rootveil pilgrimage;Receive Elder''s blessing', N'Protect all natural zones from industrialization and digital corruption', N'FAC001;FAC005', N'FAC002', NULL, N'MAG +5 in nature zones;Free healing at Rootveil shrines;Nature commune ability;Elder Taum questline', 5, N'Pre-dates all other factions. The Covenant claims the Miraverse was born from a living digital forest. Their sacred texts predict a Second Collapse.');
INSERT INTO [Factions] ([Faction_ID], [Faction_Name], [Faction_Type], [Leader_NPC_ID], [HQ_Region_ID], [Ideology], [Membership_Requirement], [Primary_Goal], [Enemy_Faction_ID], [Allied_Faction_ID], [Reputation_Scale], [Member_Perks], [Questline_Count], [Lore_Notes]) VALUES (N'FAC005', N'The Voss Collective', N'Tech/Science', N'NPC008', N'REG002', N'Progress is the only morality. Evolution — biological and digital — cannot be stopped.', N'Academic credentials or exceptional tech skill', N'Achieve total bio-digital integration for all sentient beings', N'FAC004;FAC007', N'FAC002', NULL, N'TEC +5;Crafting speed +30%;Exclusive Voss module blueprints;Dr. Voss questline', 6, N'Founded by Orlan Voss after the Collapse. Created the first neural-digital interface. Controversial for using unconsenting subjects in early trials.');
INSERT INTO [Factions] ([Faction_ID], [Faction_Name], [Faction_Type], [Leader_NPC_ID], [HQ_Region_ID], [Ideology], [Membership_Requirement], [Primary_Goal], [Enemy_Faction_ID], [Allied_Faction_ID], [Reputation_Scale], [Member_Perks], [Questline_Count], [Lore_Notes]) VALUES (N'FAC006', N'The Drifters', N'Resistance/Nomadic', N'NPC004', N'REG004', N'Freedom from all systems. No empire, no corporation, no faction owns the people.', N'Prove independence: complete solo mission without faction aid', N'Dismantle all centralized power structures across the Miraverse', N'FAC001;FAC003', N'NONE', NULL, N'AGI +5;Off-grid fast travel;Contraband immunity in Neon Sprawl;Phantom questline', 5, N'Born in the chaos of the Neon Sprawl blackouts. Started as a survival collective, grew into the most effective resistance network in the Miraverse.');
INSERT INTO [Factions] ([Faction_ID], [Faction_Name], [Faction_Type], [Leader_NPC_ID], [HQ_Region_ID], [Ideology], [Membership_Requirement], [Primary_Goal], [Enemy_Faction_ID], [Allied_Faction_ID], [Reputation_Scale], [Member_Perks], [Questline_Count], [Lore_Notes]) VALUES (N'FAC007', N'The Void Walkers', N'Mystic/Unknown', N'NPC009', N'REG008', N'The Void is not emptiness — it is everything that was, is, and will be. Walk between worlds.', N'Survive contact with Void energy;Sable''s personal invitation only', N'Understand and control the Void Rift before it consumes the Miraverse', N'FAC001;FAC003', N'NONE', NULL, N'MAG +8 near Void zones;Rift travel ability;Void Crystal drops doubled;Veylan questline', 4, N'No one founded the Void Walkers — they simply appeared after the Void Rift Incident. Some believe they are echoes of a destroyed civilization trying to warn the current one.');
INSERT INTO [Factions] ([Faction_ID], [Faction_Name], [Faction_Type], [Leader_NPC_ID], [HQ_Region_ID], [Ideology], [Membership_Requirement], [Primary_Goal], [Enemy_Faction_ID], [Allied_Faction_ID], [Reputation_Scale], [Member_Perks], [Questline_Count], [Lore_Notes]) VALUES (N'FAC008', N'The Merchant Guilds', N'Trade', N'NPC012', N'REG007', N'Trade is the lifeblood of civilization. Neutral ground, fair prices, open markets.', N'Pay guild registration fee (2000 credits);Merchant skill check', N'Control trade routes and establish economic neutrality across all regions', N'FAC003', N'FAC001;FAC002', NULL, N'CHA +5;Market value info on all items;Merchant Prince career unlock;Crimsongate questline', 5, N'The oldest trade network in the Miraverse. Survived every war by selling to both sides. The Merchant Guilds technically own the waters around Port Mira.');
INSERT INTO [Factions] ([Faction_ID], [Faction_Name], [Faction_Type], [Leader_NPC_ID], [HQ_Region_ID], [Ideology], [Membership_Requirement], [Primary_Goal], [Enemy_Faction_ID], [Allied_Faction_ID], [Reputation_Scale], [Member_Perks], [Questline_Count], [Lore_Notes]) VALUES (N'FAC009', N'The Architects', N'Tech/Engineering', N'NPC018', N'REG010', N'Structure is freedom. The world was built — it can be rebuilt. We design what comes next.', N'Craft skill level 5+;Submit a blueprint for review', N'Reconstruct the destroyed regions of the Miraverse using recovered pre-Collapse designs', N'FAC003', N'FAC005', NULL, N'Crafting XP +40%;Structure build speed +50%;Undervault access;Hex questline', 4, N'A secretive order of engineers and hackers who operate from the Undervault. Believe the Miraverse was deliberately designed — and that the blueprints still exist.');
INSERT INTO [Factions] ([Faction_ID], [Faction_Name], [Faction_Type], [Leader_NPC_ID], [HQ_Region_ID], [Ideology], [Membership_Requirement], [Primary_Goal], [Enemy_Faction_ID], [Allied_Faction_ID], [Reputation_Scale], [Member_Perks], [Questline_Count], [Lore_Notes]) VALUES (N'FAC010', N'The Phantom Bureau', N'Intelligence/Shadow', N'NPC013', N'REG002', N'Information is the only true currency. We know everything. We tell no one.', N'Unknown — invitation only', N'Compile a complete intelligence archive on every faction, house, and NPC in the Miraverse', N'FAC003;FAC008', N'FAC002', NULL, N'Stealth +15%;Enemy patrol routes revealed;Decode encrypted comms;Phantom questline', 4, N'Officially does not exist. Believed to be a splinter of the original Citadel intelligence service. Phantom may be their only active field agent.');
INSERT INTO [Factions] ([Faction_ID], [Faction_Name], [Faction_Type], [Leader_NPC_ID], [HQ_Region_ID], [Ideology], [Membership_Requirement], [Primary_Goal], [Enemy_Faction_ID], [Allied_Faction_ID], [Reputation_Scale], [Member_Perks], [Questline_Count], [Lore_Notes]) VALUES (N'FAC011', N'The Ironclaw Brotherhood', N'Warrior/Honor', N'NPC010', N'REG001', N'Every scar is a lesson. Every battle is a classroom. Honor through trial.', N'Win a Brotherhood challenge fight', N'Prove that skill and honor — not politics — should determine leadership of the Empire', N'FAC003', N'FAC001', NULL, N'STR +8;Physical damage resistance +10%;Exclusive combat skills unlock;Kael questline', 3, N'A warrior brotherhood within the Ironveil Empire that secretly disagrees with Halvorn''s political methods. Believes the Empire should be led by the strongest fighter, not the most powerful politician.');
INSERT INTO [Factions] ([Faction_ID], [Faction_Name], [Faction_Type], [Leader_NPC_ID], [HQ_Region_ID], [Ideology], [Membership_Requirement], [Primary_Goal], [Enemy_Faction_ID], [Allied_Faction_ID], [Reputation_Scale], [Member_Perks], [Questline_Count], [Lore_Notes]) VALUES (N'FAC012', N'The Ashenveil Clan', N'Resistance/Warrior', NULL, N'REG009', N'The mountains do not bow. Neither do we.', N'Complete Shattered Peaks survival trial', N'Drive the Ironveil Empire from the Shattered Peaks and reclaim their ancestral homeland', N'FAC001', N'FAC006', NULL, N'Cold resistance +20%;Mountain terrain speed +30%;Exclusive Peaks questlines;Ashenveil armor', 3, N'Survivors of the Shattered Peaks War. The Empire destroyed their original home and scattered the clan. They have been rebuilding in the ruins ever since.');

-- ── NPCs ──────────────────────────────────────────────────────────
IF OBJECT_ID(N'NPCs', N'U') IS NOT NULL DROP TABLE [NPCs];
CREATE TABLE [NPCs] (
    [NPC_ID] NVARCHAR(MAX) NOT NULL PRIMARY KEY,
    [Name] NVARCHAR(MAX) NULL,
    [Role_Class] NVARCHAR(MAX) NULL,
    [Faction_ID] NVARCHAR(MAX) NULL,
    [Region_ID] NVARCHAR(MAX) NULL,
    [House_ID] NVARCHAR(MAX) NULL,
    [Affiliation_Type] NVARCHAR(MAX) NULL,
    [Personality_Traits] NVARCHAR(MAX) NULL,
    [Signature_Skill] NVARCHAR(MAX) NULL,
    [Unlock_Condition] NVARCHAR(MAX) NULL,
    [Dialogue_Arc] NVARCHAR(MAX) NULL,
    [Voice_Style] NVARCHAR(MAX) NULL,
    [Rare] NVARCHAR(MAX) NULL,
    [Notes_Lore_JSON] NVARCHAR(MAX) NULL,
    CONSTRAINT [FK_NPCs_House_ID] FOREIGN KEY ([House_ID]) REFERENCES [Houses]([House_ID]),
    CONSTRAINT [FK_NPCs_Region_ID] FOREIGN KEY ([Region_ID]) REFERENCES [Regions]([Region_ID]),
    CONSTRAINT [FK_NPCs_Faction_ID] FOREIGN KEY ([Faction_ID]) REFERENCES [Factions]([Faction_ID])
);

INSERT INTO [NPCs] ([NPC_ID], [Name], [Role_Class], [Faction_ID], [Region_ID], [House_ID], [Affiliation_Type], [Personality_Traits], [Signature_Skill], [Unlock_Condition], [Dialogue_Arc], [Voice_Style], [Rare], [Notes_Lore_JSON]) VALUES (N'NPC001', N'ORACLE-9', N'AI Guide', NULL, NULL, NULL, N'Ally', N'Omniscient;Cryptic', N'Data Retrieval', N'Complete Tutorial', N'The Awakening Arc', N'Synthetic/Calm', N'No', N'{"lore":"Ancient AI seeded into the Miraverse at its founding. True origin unknown. Speaks in riddles and data fragments."}');
INSERT INTO [NPCs] ([NPC_ID], [Name], [Role_Class], [Faction_ID], [Region_ID], [House_ID], [Affiliation_Type], [Personality_Traits], [Signature_Skill], [Unlock_Condition], [Dialogue_Arc], [Voice_Style], [Rare], [Notes_Lore_JSON]) VALUES (N'NPC002', N'Commander Vex Halvorn', N'Military Commander', N'FAC001', N'REG001', N'HSE001', N'Hostile-Neutral', N'Ruthless;Disciplined', N'Tactical Override', N'Reach Ironspire', N'Iron Fist Arc', N'Deep/Commanding', N'No', N'{"lore":"Supreme commander of the Ironveil Empire armed forces. Lost his left eye in the Shattered Peaks War. Respects only strength."}');
INSERT INTO [NPCs] ([NPC_ID], [Name], [Role_Class], [Faction_ID], [Region_ID], [House_ID], [Affiliation_Type], [Personality_Traits], [Signature_Skill], [Unlock_Condition], [Dialogue_Arc], [Voice_Style], [Rare], [Notes_Lore_JSON]) VALUES (N'NPC003', N'Mira Solenne', N'Scholar', N'FAC002', N'REG003', N'HSE002', N'Ally', N'Curious;Warm', N'Lore Synthesis', N'Reach Verdania', N'The Living Library Arc', N'Soft/Thoughtful', N'No', N'{"lore":"Descendant of House Solenne. Keeper of the Verdant Archives. Believes knowledge should be free for all."}');
INSERT INTO [NPCs] ([NPC_ID], [Name], [Role_Class], [Faction_ID], [Region_ID], [House_ID], [Affiliation_Type], [Personality_Traits], [Signature_Skill], [Unlock_Condition], [Dialogue_Arc], [Voice_Style], [Rare], [Notes_Lore_JSON]) VALUES (N'NPC004', N'Drift', N'Rogue', N'FAC006', N'REG004', NULL, N'Neutral', N'Sarcastic;Resourceful', N'System Exploit', N'Reach Neon Sprawl', N'Ghost in the Machine Arc', N'Gritty/Casual', N'No', N'{"lore":"Nobody knows Drift''s real name. Former Syndicate data thief turned resistance leader. Lives off-grid in the Neon Sprawl underbelly."}');
INSERT INTO [NPCs] ([NPC_ID], [Name], [Role_Class], [Faction_ID], [Region_ID], [House_ID], [Affiliation_Type], [Personality_Traits], [Signature_Skill], [Unlock_Condition], [Dialogue_Arc], [Voice_Style], [Rare], [Notes_Lore_JSON]) VALUES (N'NPC005', N'Councilor Zephyra Nox', N'Political Advisor', N'FAC002', N'REG002', N'HSE003', N'Ally', N'Diplomatic;Calculating', N'Faction Diplomacy', N'Complete Citadel Intro Quest', N'The Shadow Council Arc', N'Smooth/Measured', N'No', N'{"lore":"Head of the Verdant Republic council. Secretly negotiates with all factions simultaneously. Her true allegiance remains a mystery."}');
INSERT INTO [NPCs] ([NPC_ID], [Name], [Role_Class], [Faction_ID], [Region_ID], [House_ID], [Affiliation_Type], [Personality_Traits], [Signature_Skill], [Unlock_Condition], [Dialogue_Arc], [Voice_Style], [Rare], [Notes_Lore_JSON]) VALUES (N'NPC006', N'Elder Taum', N'Spiritual Leader', N'FAC004', N'REG005', N'HSE004', N'Ally', N'Wise;Ancient', N'Nature Communion', N'Reach Rootveil', N'The Root Speaks Arc', N'Ancient/Resonant', N'Yes', N'{"lore":"Oldest living member of the Root Covenant. Claims to hear the voice of the Miraverse itself. Age unknown, possibly pre-Collapse."}');
INSERT INTO [NPCs] ([NPC_ID], [Name], [Role_Class], [Faction_ID], [Region_ID], [House_ID], [Affiliation_Type], [Personality_Traits], [Signature_Skill], [Unlock_Condition], [Dialogue_Arc], [Voice_Style], [Rare], [Notes_Lore_JSON]) VALUES (N'NPC007', N'Black Jade', N'Mercenary', N'FAC003', N'REG004', NULL, N'Hostile', N'Cold;Efficient', N'Assassination Protocol', N'Underworld Rep 3+', N'Shadows Never Rest Arc', N'Flat/Emotionless', N'Yes', N'{"lore":"The most feared assassin in the Obsidian Syndicate. No known origin. Completes every contract. No witnesses survive."}');
INSERT INTO [NPCs] ([NPC_ID], [Name], [Role_Class], [Faction_ID], [Region_ID], [House_ID], [Affiliation_Type], [Personality_Traits], [Signature_Skill], [Unlock_Condition], [Dialogue_Arc], [Voice_Style], [Rare], [Notes_Lore_JSON]) VALUES (N'NPC008', N'Dr. Lyra Voss', N'Scientist', N'FAC005', N'REG002', N'HSE005', N'Ally', N'Obsessive;Brilliant', N'Bio-Engineering', N'Reach Citadel Tech District', N'The Perfect Equation Arc', N'Rapid/Precise', N'No', N'{"lore":"Director of the Voss Collective''s biolabs. Pushes ethical limits daily. Believes biological and digital life should merge completely."}');
INSERT INTO [NPCs] ([NPC_ID], [Name], [Role_Class], [Faction_ID], [Region_ID], [House_ID], [Affiliation_Type], [Personality_Traits], [Signature_Skill], [Unlock_Condition], [Dialogue_Arc], [Voice_Style], [Rare], [Notes_Lore_JSON]) VALUES (N'NPC009', N'Sable', N'Unknown', N'FAC007', N'REG008', NULL, N'Neutral', N'Ethereal;Unsettling', N'Rift Walking', N'Discover Void Rift', N'The Nameless Arc', N'Echoing/Distant', N'Yes', N'{"lore":"Exists partially inside the Void. May be the last survivor of a civilization consumed by the Rift. Neither fully alive nor dead."}');
INSERT INTO [NPCs] ([NPC_ID], [Name], [Role_Class], [Faction_ID], [Region_ID], [House_ID], [Affiliation_Type], [Personality_Traits], [Signature_Skill], [Unlock_Condition], [Dialogue_Arc], [Voice_Style], [Rare], [Notes_Lore_JSON]) VALUES (N'NPC010', N'Kael Ironclaw', N'Warrior Champion', N'FAC001', N'REG001', N'HSE010', N'Ally', N'Honorable;Fierce', N'Iron Endurance', N'Win Ironspire Tournament', N'The Warrior''s Code Arc', N'Rough/Proud', N'No', N'{"lore":"Champion of the Ironclaw clan. Disagrees with Halvorn''s methods but serves the Empire out of loyalty to his house."}');
INSERT INTO [NPCs] ([NPC_ID], [Name], [Role_Class], [Faction_ID], [Region_ID], [House_ID], [Affiliation_Type], [Personality_Traits], [Signature_Skill], [Unlock_Condition], [Dialogue_Arc], [Voice_Style], [Rare], [Notes_Lore_JSON]) VALUES (N'NPC011', N'Serra Dawnrider', N'Nomad Scout', N'FAC008', N'REG006', N'HSE006', N'Neutral', N'Swift;Independent', N'Desert Navigation', N'Reach Sandveil', N'Sands of Memory Arc', N'Bright/Direct', N'No', N'{"lore":"Leader of the Dawnrider outriders. Maps uncharted desert territories. Sells information to the highest bidder — except the Syndicate."}');
INSERT INTO [NPCs] ([NPC_ID], [Name], [Role_Class], [Faction_ID], [Region_ID], [House_ID], [Affiliation_Type], [Personality_Traits], [Signature_Skill], [Unlock_Condition], [Dialogue_Arc], [Voice_Style], [Rare], [Notes_Lore_JSON]) VALUES (N'NPC012', N'Captain Rowan Crimsongate', N'Merchant Captain', N'FAC008', N'REG007', N'HSE007', N'Ally', N'Charismatic;Greedy', N'Trade Network', N'Reach Port Mira', N'Fortune''s Tide Arc', N'Jovial/Loud', N'No', N'{"lore":"Controls most of Port Mira''s shipping lanes. Smuggles for every faction. Claims loyalty only to profit."}');
INSERT INTO [NPCs] ([NPC_ID], [Name], [Role_Class], [Faction_ID], [Region_ID], [House_ID], [Affiliation_Type], [Personality_Traits], [Signature_Skill], [Unlock_Condition], [Dialogue_Arc], [Voice_Style], [Rare], [Notes_Lore_JSON]) VALUES (N'NPC013', N'Phantom', N'Ghost Operative', N'FAC006', N'REG004', NULL, N'Neutral', N'Paranoid;Precise', N'Ghost Protocol', N'Complete Drifters Initiation', N'No Trace Arc', N'Whispered/Clipped', N'Yes', N'{"lore":"The Drifters'' best infiltrator. Erased their own identity from every database. Even ORACLE-9 has no record of them."}');
INSERT INTO [NPCs] ([NPC_ID], [Name], [Role_Class], [Faction_ID], [Region_ID], [House_ID], [Affiliation_Type], [Personality_Traits], [Signature_Skill], [Unlock_Condition], [Dialogue_Arc], [Voice_Style], [Rare], [Notes_Lore_JSON]) VALUES (N'NPC014', N'Veylan Veilborn', N'Dimensional Mystic', N'FAC007', N'REG008', N'HSE009', N'Neutral', N'Mystical;Serene', N'Dimensional Sight', N'Void Walker Rep 2+', N'What Lies Between Arc', N'Layered/Overlapping', N'Yes', N'{"lore":"Born during the Void Rift Incident. Can perceive multiple timelines simultaneously. Serves as oracle for the Void Walkers."}');
INSERT INTO [NPCs] ([NPC_ID], [Name], [Role_Class], [Faction_ID], [Region_ID], [House_ID], [Affiliation_Type], [Personality_Traits], [Signature_Skill], [Unlock_Condition], [Dialogue_Arc], [Voice_Style], [Rare], [Notes_Lore_JSON]) VALUES (N'NPC015', N'Minister Aldric Nox', N'Political Schemer', N'FAC001', N'REG002', N'HSE003', N'Hostile-Neutral', N'Manipulative;Charming', N'Political Leverage', N'Citadel Faction Rep 1+', N'The Web of Power Arc', N'Silky/Dangerous', N'No', N'{"lore":"Younger brother of Councilor Zephyra Nox. Works covertly for the Ironveil Empire while posing as a Republic diplomat."}');
INSERT INTO [NPCs] ([NPC_ID], [Name], [Role_Class], [Faction_ID], [Region_ID], [House_ID], [Affiliation_Type], [Personality_Traits], [Signature_Skill], [Unlock_Condition], [Dialogue_Arc], [Voice_Style], [Rare], [Notes_Lore_JSON]) VALUES (N'NPC016', N'Zara Obsidian', N'Crime Boss', N'FAC003', N'REG004', N'HSE008', N'Hostile', N'Cunning;Territorial', N'Black Market Access', N'Syndicate Intro Quest', N'Queen of the Dark Arc', N'Sultry/Threatening', N'Yes', N'{"lore":"True head of the Obsidian Syndicate. Black Jade answers to her. Controls every illegal operation in the Neon Sprawl."}');
INSERT INTO [NPCs] ([NPC_ID], [Name], [Role_Class], [Faction_ID], [Region_ID], [House_ID], [Affiliation_Type], [Personality_Traits], [Signature_Skill], [Unlock_Condition], [Dialogue_Arc], [Voice_Style], [Rare], [Notes_Lore_JSON]) VALUES (N'NPC017', N'Prof. Elian Solenne', N'Academic Historian', N'FAC002', N'REG003', N'HSE002', N'Ally', N'Absent-Minded;Passionate', N'Ancient Knowledge', N'Verdania Rep 1+', N'The Lost Pages Arc', N'Distracted/Excited', N'No', N'{"lore":"Mira Solenne''s uncle. World authority on pre-Collapse history. Accidentally discovers the truth about House Mireth."}');
INSERT INTO [NPCs] ([NPC_ID], [Name], [Role_Class], [Faction_ID], [Region_ID], [House_ID], [Affiliation_Type], [Personality_Traits], [Signature_Skill], [Unlock_Condition], [Dialogue_Arc], [Voice_Style], [Rare], [Notes_Lore_JSON]) VALUES (N'NPC018', N'Hex', N'Tech Anarchist', N'FAC006', N'REG009', NULL, N'Neutral', N'Chaotic;Idealistic', N'System Overload', N'Undervault Exploration', N'Burn It Down Arc', N'Manic/Fast', N'No', N'{"lore":"Self-taught hacker who believes all digital systems should be free. Lives in the Undervault ruins. Allies with the Drifters loosely."}');
INSERT INTO [NPCs] ([NPC_ID], [Name], [Role_Class], [Faction_ID], [Region_ID], [House_ID], [Affiliation_Type], [Personality_Traits], [Signature_Skill], [Unlock_Condition], [Dialogue_Arc], [Voice_Style], [Rare], [Notes_Lore_JSON]) VALUES (N'NPC019', N'Asha Taum', N'Nature Warden', N'FAC004', N'REG005', N'HSE004', N'Ally', N'Gentle;Fierce', N'Nature Bond', N'Root Covenant Rep 1+', N'The Last Grove Arc', N'Melodic/Firm', N'No', N'{"lore":"Elder Taum''s granddaughter and likely successor. Secretly studied tech augmentation to better protect the Rootveil from industrial encroachment."}');
INSERT INTO [NPCs] ([NPC_ID], [Name], [Role_Class], [Faction_ID], [Region_ID], [House_ID], [Affiliation_Type], [Personality_Traits], [Signature_Skill], [Unlock_Condition], [Dialogue_Arc], [Voice_Style], [Rare], [Notes_Lore_JSON]) VALUES (N'NPC020', N'The Archivist', N'Unknown', NULL, N'REG010', NULL, N'Neutral', N'Meticulous;Eerie', N'Lore Recall', N'Discover Undervault', N'Beneath the Record Arc', N'Static/Formal', N'Yes', N'{"lore":"An entity of unknown origin that catalogs everything that has ever happened in the Miraverse. May be a fragment of ORACLE-9."}');

-- ── Careers ──────────────────────────────────────────────────────────
IF OBJECT_ID(N'Careers', N'U') IS NOT NULL DROP TABLE [Careers];
CREATE TABLE [Careers] (
    [Career_ID] NVARCHAR(MAX) NOT NULL PRIMARY KEY,
    [Career_Name] NVARCHAR(MAX) NULL,
    [Career_Category] NVARCHAR(MAX) NULL,
    [Primary_Stat] NVARCHAR(MAX) NULL,
    [Starting_Region_ID] NVARCHAR(MAX) NULL,
    [Starting_Faction_ID] NVARCHAR(MAX) NULL,
    [Playstyle_Description] NVARCHAR(MAX) NULL,
    [Signature_Ability] NVARCHAR(MAX) NULL,
    [Passive_Bonus] NVARCHAR(MAX) NULL,
    [Level_Cap] INT NULL,
    [Prestige_Path] NVARCHAR(MAX) NULL,
    [Prestige_Career_Name] NVARCHAR(MAX) NULL,
    [Unlock_Cost] FLOAT NULL,
    [Compatible_Modules] NVARCHAR(MAX) NULL,
    [Lore_Notes] NVARCHAR(MAX) NULL,
    CONSTRAINT [FK_Careers_Starting_Faction_ID] FOREIGN KEY ([Starting_Faction_ID]) REFERENCES [Factions]([Faction_ID]),
    CONSTRAINT [FK_Careers_Starting_Region_ID] FOREIGN KEY ([Starting_Region_ID]) REFERENCES [Regions]([Region_ID])
);

INSERT INTO [Careers] ([Career_ID], [Career_Name], [Career_Category], [Primary_Stat], [Starting_Region_ID], [Starting_Faction_ID], [Playstyle_Description], [Signature_Ability], [Passive_Bonus], [Level_Cap], [Prestige_Path], [Prestige_Career_Name], [Unlock_Cost], [Compatible_Modules], [Lore_Notes]) VALUES (N'CAR001', N'Shadowblade', N'Combat/Hybrid', N'AGI', N'REG004', N'FAC006', N'Stealth assassin who blends combat prowess with digital infiltration. Excels at eliminating single targets undetected.', N'Shadow Veil (30s full invisibility + guaranteed crit on first strike)', N'AGI +3; Critical Damage +15%; Backstab damage doubled', 60, N'Y', N'Phantom Wraith', NULL, N'Shadow Weave Armor;Ghost Protocol Cloak;Arc Blade;Data Spike', N'The Shadowblade discipline was developed in the Neon Sprawl by Drifter operatives who needed to survive Syndicate enforcers.');
INSERT INTO [Careers] ([Career_ID], [Career_Name], [Career_Category], [Primary_Stat], [Starting_Region_ID], [Starting_Faction_ID], [Playstyle_Description], [Signature_Ability], [Passive_Bonus], [Level_Cap], [Prestige_Path], [Prestige_Career_Name], [Unlock_Cost], [Compatible_Modules], [Lore_Notes]) VALUES (N'CAR002', N'Netrunner', N'Tech', N'TEC', N'REG004', N'FAC005', N'Digital warfare specialist who hacks systems, controls drones, and rewrites reality through the MiraOS.', N'Neural Overdrive (triple processing speed for 20s, jack into any system remotely)', N'TEC +5; Hack success rate +25%; Device control range +50m', 60, N'Y', N'Phantom Coder', NULL, N'Neural Overclocking Chip;Rift Eye Lens;Data Spike;Ghost Protocol Cloak', N'Born from the first generation of citizens who could interface directly with the Miraverse''s digital layer.');
INSERT INTO [Careers] ([Career_ID], [Career_Name], [Career_Category], [Primary_Stat], [Starting_Region_ID], [Starting_Faction_ID], [Playstyle_Description], [Signature_Ability], [Passive_Bonus], [Level_Cap], [Prestige_Path], [Prestige_Career_Name], [Unlock_Cost], [Compatible_Modules], [Lore_Notes]) VALUES (N'CAR003', N'Arcanist', N'Magic', N'MAG', N'REG008', N'FAC007', N'Master of void and arcane energies. Channels dimensional power into devastating spells and protective barriers.', N'Arcane Surge (channel all MAG into single AOE blast; 60s cooldown)', N'MAG +5; Spell damage +20%; Mana regeneration +30%', 60, N'Y', N'Void Arcanist', NULL, N'Void Resonator;Resonance Gauntlets;Rift Eye Lens;Root Mantle', N'Arcanists first appeared after the Void Rift Incident, when some survivors discovered they could channel Rift energy directly.');
INSERT INTO [Careers] ([Career_ID], [Career_Name], [Career_Category], [Primary_Stat], [Starting_Region_ID], [Starting_Faction_ID], [Playstyle_Description], [Signature_Ability], [Passive_Bonus], [Level_Cap], [Prestige_Path], [Prestige_Career_Name], [Unlock_Cost], [Compatible_Modules], [Lore_Notes]) VALUES (N'CAR004', N'Diplomat', N'Social', N'CHA', N'REG002', N'FAC002', N'Master negotiator and political operative. Resolves conflicts through words, favors, and carefully placed information.', N'Silver Tongue (force NPC dialogue check success for 60s; cannot be used in combat)', N'CHA +5; Reputation gains +20%; NPC hostility reduced by 2 tiers', 60, N'Y', N'Grand Envoy', NULL, N'Merchant''s Signet Ring;BioMonitor;FactionHub', N'Diplomats are trained in the Citadel''s Republic academies. Their skills are equally effective in boardrooms and battlefields.');
INSERT INTO [Careers] ([Career_ID], [Career_Name], [Career_Category], [Primary_Stat], [Starting_Region_ID], [Starting_Faction_ID], [Playstyle_Description], [Signature_Ability], [Passive_Bonus], [Level_Cap], [Prestige_Path], [Prestige_Career_Name], [Unlock_Cost], [Compatible_Modules], [Lore_Notes]) VALUES (N'CAR005', N'Bio-Engineer', N'Tech/Science', N'INT', N'REG002', N'FAC005', N'Biological and digital augmentation specialist. Modifies themselves and allies with cutting-edge Voss Collective tech.', N'Bio-Sync Cascade (apply all active bio-mods to entire party for 45s)', N'INT +4; Crafting speed +25%; Augmentation effects +15%', 60, N'Y', N'Apex Augmentor', NULL, N'Biotic Shield;Resonance Gauntlets;Neural Overclocking Chip;BioMonitor', N'Created by the Voss Collective to field-test experimental augmentations. Bio-Engineers blur the line between human and machine.');
INSERT INTO [Careers] ([Career_ID], [Career_Name], [Career_Category], [Primary_Stat], [Starting_Region_ID], [Starting_Faction_ID], [Playstyle_Description], [Signature_Ability], [Passive_Bonus], [Level_Cap], [Prestige_Path], [Prestige_Career_Name], [Unlock_Cost], [Compatible_Modules], [Lore_Notes]) VALUES (N'CAR006', N'Warlord', N'Combat', N'STR', N'REG001', N'FAC001', N'Frontline heavy combatant who inspires allies and crushes enemies through sheer force of will and physical power.', N'Battle Cry (all nearby allies gain STR +10 and damage immunity for 8s; 90s cooldown)', N'STR +6; Physical damage +20%; Party morale aura', 60, N'Y', N'Iron Sovereign', NULL, N'Skybreaker Cannon;Biotic Shield;Resonance Gauntlets', N'The Warlord path is the oldest career in the Miraverse, predating even the First Collapse. The Ironveil Empire reveres them.');
INSERT INTO [Careers] ([Career_ID], [Career_Name], [Career_Category], [Primary_Stat], [Starting_Region_ID], [Starting_Faction_ID], [Playstyle_Description], [Signature_Ability], [Passive_Bonus], [Level_Cap], [Prestige_Path], [Prestige_Career_Name], [Unlock_Cost], [Compatible_Modules], [Lore_Notes]) VALUES (N'CAR007', N'Void Walker', N'Magic/Hybrid', N'MAG', N'REG008', N'FAC007', N'Dimensional traveler who exists between realities. Can phase through walls, see across the Void, and summon rift entities.', N'Void Step (teleport anywhere in current zone instantly; 45s cooldown)', N'MAG +4; Void resistance +50%; Invisible to non-Void entities', 60, N'Y', N'Rift Sovereign', NULL, N'Void Resonator;Rift Eye Lens;Ghost Protocol Cloak;Root Mantle', N'Only those touched by Void energy during the Rift Incident can truly walk this path. The Void Walkers teach it to very few outsiders.');
INSERT INTO [Careers] ([Career_ID], [Career_Name], [Career_Category], [Primary_Stat], [Starting_Region_ID], [Starting_Faction_ID], [Playstyle_Description], [Signature_Ability], [Passive_Bonus], [Level_Cap], [Prestige_Path], [Prestige_Career_Name], [Unlock_Cost], [Compatible_Modules], [Lore_Notes]) VALUES (N'CAR008', N'Merchant Prince', N'Social/Trade', N'CHA', N'REG007', N'FAC008', N'Economic empire builder who controls markets, bribes enemies, and wins wars with gold instead of steel.', N'Market Monopoly (control all item prices in current region for 1 hour; massive currency gain)', N'CHA +4; All item purchase prices -20%; Sell prices +25%', 60, N'Y', N'Trade Emperor', NULL, N'Merchant''s Signet Ring;BioMonitor;BlackMarket.exe', N'Born from the merchant dynasties of Port Mira. The Merchant Prince career treats every interaction as a transaction.');
INSERT INTO [Careers] ([Career_ID], [Career_Name], [Career_Category], [Primary_Stat], [Starting_Region_ID], [Starting_Faction_ID], [Playstyle_Description], [Signature_Ability], [Passive_Bonus], [Level_Cap], [Prestige_Path], [Prestige_Career_Name], [Unlock_Cost], [Compatible_Modules], [Lore_Notes]) VALUES (N'CAR009', N'Pathfinder', N'Exploration', N'AGI', N'REG006', N'FAC008', N'Master explorer and survivalist who maps uncharted territories and unlocks regions others cannot access.', N'Trailblaze (unlock any locked fast travel hub instantly; reveal entire region map)', N'AGI +3; Movement speed +20%; Resource discovery rate +40%', 60, N'Y', N'Cartographer Prime', NULL, N'MiraMap Pro;RouteRunner;Desert survival modules', N'Pathfinders follow in the tradition of the Dawnrider scouts. Their maps have won more battles than any army.');
INSERT INTO [Careers] ([Career_ID], [Career_Name], [Career_Category], [Primary_Stat], [Starting_Region_ID], [Starting_Faction_ID], [Playstyle_Description], [Signature_Ability], [Passive_Bonus], [Level_Cap], [Prestige_Path], [Prestige_Career_Name], [Unlock_Cost], [Compatible_Modules], [Lore_Notes]) VALUES (N'CAR010', N'Artificer', N'Tech/Magic', N'TEC', N'REG010', N'FAC009', N'Engineer-mage who crafts custom weapons, mechanical constructs, and enchanted devices from salvaged components.', N'Construct Deploy (summon a combat-ready mechanical construct for 3 minutes)', N'TEC +3; MAG +2; Crafting quality +30%; Salvage yield +25%', 60, N'Y', N'Grand Artificer', NULL, N'Neural Overclocking Chip;Arc Blade;Skybreaker Cannon;Resonance Gauntlets', N'Artificers emerged from the Undervault''s Architect order, fusing pre-Collapse engineering with post-Collapse arcane energy.');
INSERT INTO [Careers] ([Career_ID], [Career_Name], [Career_Category], [Primary_Stat], [Starting_Region_ID], [Starting_Faction_ID], [Playstyle_Description], [Signature_Ability], [Passive_Bonus], [Level_Cap], [Prestige_Path], [Prestige_Career_Name], [Unlock_Cost], [Compatible_Modules], [Lore_Notes]) VALUES (N'CAR011', N'Lore Keeper', N'Academic', N'INT', N'REG003', N'FAC002', N'Scholar-adventurer who unlocks ancient knowledge, translates dead languages, and weaponizes history.', N'Ancient Revelation (instantly reveal all lore, secrets, and hidden quests in current region)', N'INT +5; Lore collection XP +50%; NPC knowledge dialogue always available', 60, N'Y', N'Archive Master', NULL, N'MemoryVault;EchoID;MiraMap Pro', N'Trained by House Solenne in the Verdant Archive. Lore Keepers are the living memory of the Miraverse.');
INSERT INTO [Careers] ([Career_ID], [Career_Name], [Career_Category], [Primary_Stat], [Starting_Region_ID], [Starting_Faction_ID], [Playstyle_Description], [Signature_Ability], [Passive_Bonus], [Level_Cap], [Prestige_Path], [Prestige_Career_Name], [Unlock_Cost], [Compatible_Modules], [Lore_Notes]) VALUES (N'CAR012', N'Ghost', N'Stealth/Combat', N'AGI', N'REG004', N'FAC010', N'Ultimate stealth operative who exists as a ghost in every system — no records, no trace, no witnesses.', N'Phantom Cloak (complete invisibility + system ghost status for 60s; AI enemies cannot detect)', N'AGI +4; All tracking systems blind to player; Stealth kills untraceable', 60, N'Y', N'Null Agent', NULL, N'Ghost Protocol Cloak;Shadow Weave Armor;EchoID;Data Spike', N'Ghosts are trained by the Phantom Bureau. They are legally erased individuals who weaponize their nonexistence.');
INSERT INTO [Careers] ([Career_ID], [Career_Name], [Career_Category], [Primary_Stat], [Starting_Region_ID], [Starting_Faction_ID], [Playstyle_Description], [Signature_Ability], [Passive_Bonus], [Level_Cap], [Prestige_Path], [Prestige_Career_Name], [Unlock_Cost], [Compatible_Modules], [Lore_Notes]) VALUES (N'CAR013', N'Psionic', N'Magic/Social', N'MAG', N'REG012', N'FAC007', N'Mind-bender who reads thoughts, controls enemies, and projects consciousness across the digital layer.', N'Mind Shatter (stun all enemies in range for 10s + force surrender on humanoids)', N'MAG +3; CHA +3; Enemies reveal intentions 10s before acting', 60, N'Y', N'Overmind', NULL, N'Neural Overclocking Chip;Rift Eye Lens;NeuralLink', N'Psionics emerged when the first Netrunners pushed their neural interfaces too far, awakening latent abilities no one expected.');
INSERT INTO [Careers] ([Career_ID], [Career_Name], [Career_Category], [Primary_Stat], [Starting_Region_ID], [Starting_Faction_ID], [Playstyle_Description], [Signature_Ability], [Passive_Bonus], [Level_Cap], [Prestige_Path], [Prestige_Career_Name], [Unlock_Cost], [Compatible_Modules], [Lore_Notes]) VALUES (N'CAR014', N'Beastmaster', N'Survival/Combat', N'STR', N'REG005', N'FAC004', N'Nature warrior who bonds with Miraverse creatures and commands them in battle.', N'Alpha Call (summon pack of 3 bonded creatures; creatures gain +50% power for 30s)', N'STR +3; All bonded creatures +25% stats; Nature zone speed +30%', 60, N'Y', N'Apex Predator', NULL, N'Root Mantle;Biotic Shield;BioMonitor', N'Taught by the Root Covenant as a means of defending Rootveil from industrial incursion. Beastmasters treat all creatures as kin.');
INSERT INTO [Careers] ([Career_ID], [Career_Name], [Career_Category], [Primary_Stat], [Starting_Region_ID], [Starting_Faction_ID], [Playstyle_Description], [Signature_Ability], [Passive_Bonus], [Level_Cap], [Prestige_Path], [Prestige_Career_Name], [Unlock_Cost], [Compatible_Modules], [Lore_Notes]) VALUES (N'CAR015', N'Gunslinger', N'Combat', N'AGI', N'REG001', N'FAC001', N'Rapid-fire ranged specialist who overwhelms enemies with speed, trick shots, and explosive rounds.', N'Bullet Storm (fire 20 rounds in 3s with 100% accuracy; ignores armor for duration)', N'AGI +4; Ranged damage +25%; Reload speed +50%', 60, N'Y', N'Dead-Eye', NULL, N'Skybreaker Cannon;Arc Blade;Ghost Protocol Cloak', N'A career born from the Imperial sharpshooter corps. Many Gunslingers defect to the Drifters, taking their skills with them.');
INSERT INTO [Careers] ([Career_ID], [Career_Name], [Career_Category], [Primary_Stat], [Starting_Region_ID], [Starting_Faction_ID], [Playstyle_Description], [Signature_Ability], [Passive_Bonus], [Level_Cap], [Prestige_Path], [Prestige_Career_Name], [Unlock_Cost], [Compatible_Modules], [Lore_Notes]) VALUES (N'CAR016', N'Medic', N'Support/Tech', N'INT', N'REG002', N'FAC005', N'Combat medic and field surgeon who keeps allies alive under any conditions and weaponizes medical knowledge.', N'Emergency Revival (instantly revive all downed allies to 50% HP; 120s cooldown)', N'INT +4; Party healing +40%; Status effect cure speed +60%', 60, N'Y', N'Miracle Worker', NULL, N'BioMonitor;Biotic Shield;Neural Overclocking Chip', N'Medics were created by the Voss Collective but are welcomed by all factions — even enemies rarely fire on a confirmed Medic.');
INSERT INTO [Careers] ([Career_ID], [Career_Name], [Career_Category], [Primary_Stat], [Starting_Region_ID], [Starting_Faction_ID], [Playstyle_Description], [Signature_Ability], [Passive_Bonus], [Level_Cap], [Prestige_Path], [Prestige_Career_Name], [Unlock_Cost], [Compatible_Modules], [Lore_Notes]) VALUES (N'CAR017', N'Hacker', N'Tech', N'TEC', N'REG004', N'FAC006', N'Pure digital warfare specialist who disables systems, steals data, and weaponizes the MiraOS itself.', N'System Collapse (shut down all electronic systems in current zone for 30s)', N'TEC +5; All electronic enemies disabled +15s; Black market prices -30%', 60, N'Y', N'Zero Day', NULL, N'Data Spike;Neural Overclocking Chip;VoidScan;BlackMarket.exe', N'Hackers are the chaotic edge of Netrunning — less precision, more destruction. The Syndicate recruits them; the Drifters create them.');
INSERT INTO [Careers] ([Career_ID], [Career_Name], [Career_Category], [Primary_Stat], [Starting_Region_ID], [Starting_Faction_ID], [Playstyle_Description], [Signature_Ability], [Passive_Bonus], [Level_Cap], [Prestige_Path], [Prestige_Career_Name], [Unlock_Cost], [Compatible_Modules], [Lore_Notes]) VALUES (N'CAR018', N'Warlock', N'Magic', N'MAG', N'REG008', N'FAC007', N'Dark magic specialist who draws power from forbidden void energies and sacrifices for devastating effects.', N'Soul Drain (absorb life force from all nearby enemies; refill own HP and MAG fully)', N'MAG +6; Dark damage +30%; Life steal on all attacks', 60, N'Y', N'Void Lord', NULL, N'Void Resonator;Root Mantle;Resonance Gauntlets', N'Warlocks walk a line the Void Walkers consider dangerous. They take more from the Void than they give back — and the Void remembers.');
INSERT INTO [Careers] ([Career_ID], [Career_Name], [Career_Category], [Primary_Stat], [Starting_Region_ID], [Starting_Faction_ID], [Playstyle_Description], [Signature_Ability], [Passive_Bonus], [Level_Cap], [Prestige_Path], [Prestige_Career_Name], [Unlock_Cost], [Compatible_Modules], [Lore_Notes]) VALUES (N'CAR019', N'Commander', N'Combat/Social', N'STR', N'REG001', N'FAC001', N'Tactical battlefield leader who coordinates entire teams, issues strategic orders, and turns squads into weapons.', N'Tactical Command (all party members act simultaneously for 15s; AP costs halved)', N'STR +2; CHA +3; Party XP gain +15%; Ally damage +20%', 60, N'Y', N'Grand Marshal', NULL, N'Skybreaker Cannon;Biotic Shield;FactionHub;ThreatMatrix', N'The Commander career is taught exclusively in Imperial War Colleges but its skills apply to any conflict.');
INSERT INTO [Careers] ([Career_ID], [Career_Name], [Career_Category], [Primary_Stat], [Starting_Region_ID], [Starting_Faction_ID], [Playstyle_Description], [Signature_Ability], [Passive_Bonus], [Level_Cap], [Prestige_Path], [Prestige_Career_Name], [Unlock_Cost], [Compatible_Modules], [Lore_Notes]) VALUES (N'CAR020', N'Drifter', N'Survival/Hybrid', N'AGI', N'REG004', N'FAC006', N'Pure survival generalist who excels in every environment but masters none — the ultimate improviser.', N'Adapt (copy the last ability used by any NPC or player for 60s)', N'AGI +2; All stats +1; Survival crafting from any materials; No faction hostility penalty', 60, N'Y', N'Nomad Prime', NULL, N'MiraMap Pro;RouteRunner;EchoID;MemoryVault', N'The Drifter career is the oldest free path in the Miraverse. No house, no faction, no allegiance — just survival and freedom.');

-- ── Modules ──────────────────────────────────────────────────────────
IF OBJECT_ID(N'Modules', N'U') IS NOT NULL DROP TABLE [Modules];
CREATE TABLE [Modules] (
    [Module_ID] NVARCHAR(MAX) NOT NULL PRIMARY KEY,
    [Module_Name] NVARCHAR(MAX) NULL,
    [Module_Type] NVARCHAR(MAX) NULL,
    [Tier] INT NULL,
    [Stat_Bonus_JSON] NVARCHAR(MAX) NULL,
    [Compatible_Career_IDs] NVARCHAR(MAX) NULL,
    [Effect_Description] NVARCHAR(MAX) NULL,
    [Craft_Materials] NVARCHAR(MAX) NULL,
    [Drop_Source] NVARCHAR(MAX) NULL,
    [Market_Value] FLOAT NULL,
    [Rarity] NVARCHAR(MAX) NULL,
    [Equip_Slot] NVARCHAR(MAX) NULL,
    [Stack_Limit] INT NULL,
    [Lore_Notes] NVARCHAR(MAX) NULL
);

INSERT INTO [Modules] ([Module_ID], [Module_Name], [Module_Type], [Tier], [Stat_Bonus_JSON], [Compatible_Career_IDs], [Effect_Description], [Craft_Materials], [Drop_Source], [Market_Value], [Rarity], [Equip_Slot], [Stack_Limit], [Lore_Notes]) VALUES (N'MOD001', N'Neural Overclocking Chip', N'Neural', 3, N'{"TEC":4,"INT":3}', N'CAR002;CAR005;CAR010;CAR013', N'Boosts processing speed by 200%. Enables multi-system simultaneous hack. Overheats after 30s continuous use.', N'Quantum Circuits x3;Neural Polymer x2;Void-touched Wire x1', N'Voss Institute drop / Craft', 8500.0, N'Rare', N'Neural Slot', 1, N'Developed by the Voss Collective as a performance enhancement. Early models caused psychic feedback — the current version is merely dangerous.');
INSERT INTO [Modules] ([Module_ID], [Module_Name], [Module_Type], [Tier], [Stat_Bonus_JSON], [Compatible_Career_IDs], [Effect_Description], [Craft_Materials], [Drop_Source], [Market_Value], [Rarity], [Equip_Slot], [Stack_Limit], [Lore_Notes]) VALUES (N'MOD002', N'Shadow Weave Armor', N'Armor', 4, N'{"AGI":5,"DEF":8}', N'CAR001;CAR012', N'Adaptive camouflage that bends light around the wearer. Reduces detection range by 75%. Degrades in extreme heat.', N'Void-touched Fiber x4;Dark Crystal x2;Stealth Polymer x3', N'Obsidian Syndicate drop / Craft', 14200.0, N'Epic', N'Chest Slot', 1, N'Woven from a material recovered from the Void Rift. The Syndicate reverse-engineered it from a Void Walker''s cloak.');
INSERT INTO [Modules] ([Module_ID], [Module_Name], [Module_Type], [Tier], [Stat_Bonus_JSON], [Compatible_Career_IDs], [Effect_Description], [Craft_Materials], [Drop_Source], [Market_Value], [Rarity], [Equip_Slot], [Stack_Limit], [Lore_Notes]) VALUES (N'MOD003', N'Void Resonator', N'Weapon', 5, N'{"MAG":10,"TEC":3}', N'CAR003;CAR007;CAR018', N'Channels Void energy into a focused beam that ignores all physical armor. Causes dimensional instability on hit. 10% chance to open a rift.', N'Void Crystal x5;Dimensional Shard x3;Ancient Core x2', N'Void Rift boss drop only', 38000.0, N'Legendary', N'Weapon Slot', 1, N'One of three weapons known to affect entities that exist outside normal reality. The other two are unaccounted for.');
INSERT INTO [Modules] ([Module_ID], [Module_Name], [Module_Type], [Tier], [Stat_Bonus_JSON], [Compatible_Career_IDs], [Effect_Description], [Craft_Materials], [Drop_Source], [Market_Value], [Rarity], [Equip_Slot], [Stack_Limit], [Lore_Notes]) VALUES (N'MOD004', N'Arc Blade', N'Weapon', 2, N'{"AGI":2,"STR":3}', N'CAR001;CAR006;CAR015', N'Electrified short blade that chains lightning between adjacent enemies. Deals bonus damage to mechanical targets.', N'Copper Core x3;Electric Cell x2;Tempered Steel x2', N'General weapon drop / Craft', 2400.0, N'Uncommon', N'Weapon Slot', 1, N'Standard-issue sidearm for mid-tier Ironveil soldiers. Many have been stolen and modified by Drifter mechanics.');
INSERT INTO [Modules] ([Module_ID], [Module_Name], [Module_Type], [Tier], [Stat_Bonus_JSON], [Compatible_Career_IDs], [Effect_Description], [Craft_Materials], [Drop_Source], [Market_Value], [Rarity], [Equip_Slot], [Stack_Limit], [Lore_Notes]) VALUES (N'MOD005', N'Biotic Shield', N'Armor', 3, N'{"DEF":10,"INT":2}', N'CAR005;CAR006;CAR016;CAR019', N'Projects a bio-energetic barrier absorbing up to 500 damage before breaking. Regenerates over 60s. Immune to toxin damage.', N'Bio-Resin x4;Nano-Weave x2;Voss Polymer x2', N'Voss Institute craft / Drop', 7800.0, N'Rare', N'Chest Slot', 1, N'A Voss Collective innovation. The shield is technically alive — a thin layer of engineered organisms that sacrifice themselves to protect the wearer.');
INSERT INTO [Modules] ([Module_ID], [Module_Name], [Module_Type], [Tier], [Stat_Bonus_JSON], [Compatible_Career_IDs], [Effect_Description], [Craft_Materials], [Drop_Source], [Market_Value], [Rarity], [Equip_Slot], [Stack_Limit], [Lore_Notes]) VALUES (N'MOD006', N'Root Mantle', N'Armor', 2, N'{"MAG":3,"DEF":5}', N'CAR003;CAR007;CAR014;CAR018', N'Living armor that absorbs nature energy. Grants slow health regeneration in natural zones. Hardens to stone vs fire damage.', N'Root Crystal x3;Ancient Bark x3;Nature Essence x2', N'Rootveil zone drop', 3100.0, N'Uncommon', N'Chest Slot', 1, N'Grown rather than forged. The Root Covenant grows these mantles over decades. Accepting one is considered a sacred honor.');
INSERT INTO [Modules] ([Module_ID], [Module_Name], [Module_Type], [Tier], [Stat_Bonus_JSON], [Compatible_Career_IDs], [Effect_Description], [Craft_Materials], [Drop_Source], [Market_Value], [Rarity], [Equip_Slot], [Stack_Limit], [Lore_Notes]) VALUES (N'MOD007', N'Resonance Gauntlets', N'Implant', 3, N'{"STR":4,"MAG":3}', N'CAR003;CAR005;CAR006;CAR010', N'Augmented gauntlets that amplify both physical strikes and arcane channeling. Melee hits deal bonus resonance damage.', N'Resonite x3;Arcane Conductor x2;Steel Polymer x2', N'Undervault craft / Drop', 6900.0, N'Rare', N'Hands Slot', 1, N'Salvaged from a pre-Collapse military prototype. Someone was building soldiers who could fight both physically and magically.');
INSERT INTO [Modules] ([Module_ID], [Module_Name], [Module_Type], [Tier], [Stat_Bonus_JSON], [Compatible_Career_IDs], [Effect_Description], [Craft_Materials], [Drop_Source], [Market_Value], [Rarity], [Equip_Slot], [Stack_Limit], [Lore_Notes]) VALUES (N'MOD008', N'Skybreaker Cannon', N'Weapon', 5, N'{"STR":6,"TEC":4}', N'CAR006;CAR010;CAR015;CAR019', N'Fires a supercharged plasma burst that destroys cover and deals massive AOE damage. Single-use charge per battle.', N'Plasma Core x4;Titanium Frame x3;Energy Cell x5', N'Shattered Peaks military cache', 42000.0, N'Legendary', N'Weapon Slot', 1, N'The weapon that ended the Shattered Peaks War. The Empire claims only 12 were ever built. The Ashenveil Clan says there were 20 — and they have 8.');
INSERT INTO [Modules] ([Module_ID], [Module_Name], [Module_Type], [Tier], [Stat_Bonus_JSON], [Compatible_Career_IDs], [Effect_Description], [Craft_Materials], [Drop_Source], [Market_Value], [Rarity], [Equip_Slot], [Stack_Limit], [Lore_Notes]) VALUES (N'MOD009', N'Ghost Protocol Cloak', N'Implant', 4, N'{"AGI":6,"TEC":2}', N'CAR001;CAR002;CAR007;CAR012', N'Full-spectrum stealth cloak. Renders wearer invisible to cameras, heat sensors, AI detection, and Void sight for 45s.', N'Dark Crystal x3;Signal Dampener x3;Stealth Polymer x4', N'Phantom Bureau cache / Craft', 18500.0, N'Epic', N'Back Slot', 1, N'Standard issue for Phantom Bureau field agents. The manufacturing facility''s location is one of the most guarded secrets in the Miraverse.');
INSERT INTO [Modules] ([Module_ID], [Module_Name], [Module_Type], [Tier], [Stat_Bonus_JSON], [Compatible_Career_IDs], [Effect_Description], [Craft_Materials], [Drop_Source], [Market_Value], [Rarity], [Equip_Slot], [Stack_Limit], [Lore_Notes]) VALUES (N'MOD010', N'Merchant''s Signet Ring', N'Environmental', 1, N'{"CHA":3}', N'CAR004;CAR008;CAR009;CAR020', N'All market prices reduced by 10%. Grants access to hidden merchant dialogue options. Recognized by all Guild members.', N'Gold Alloy x2;Guild Seal x1', N'Port Mira merchant quest reward / Purchase', 800.0, N'Common', N'Accessory Slot', 3, N'Every Merchant Guild member receives one upon joining. The ring contains an encrypted signal that identifies the wearer to Guild security systems.');
INSERT INTO [Modules] ([Module_ID], [Module_Name], [Module_Type], [Tier], [Stat_Bonus_JSON], [Compatible_Career_IDs], [Effect_Description], [Craft_Materials], [Drop_Source], [Market_Value], [Rarity], [Equip_Slot], [Stack_Limit], [Lore_Notes]) VALUES (N'MOD011', N'Rift Eye Lens', N'Neural', 4, N'{"MAG":4,"INT":3,"TEC":2}', N'CAR002;CAR003;CAR007;CAR013', N'Allows wearer to see through walls, detect Void entities, read digital code in physical space, and spot hidden compartments.', N'Void Crystal x2;Bio-Lens x2;Neural Polymer x1', N'Void Rift exploration', 12000.0, N'Epic', N'Neural Slot', 1, N'Grown from a crystallized fragment of Void energy. The Void Walkers consider anyone wearing one to be partially in the Void.');
INSERT INTO [Modules] ([Module_ID], [Module_Name], [Module_Type], [Tier], [Stat_Bonus_JSON], [Compatible_Career_IDs], [Effect_Description], [Craft_Materials], [Drop_Source], [Market_Value], [Rarity], [Equip_Slot], [Stack_Limit], [Lore_Notes]) VALUES (N'MOD012', N'Data Spike', N'Weapon', 2, N'{"TEC":4,"INT":1}', N'CAR002;CAR012;CAR017', N'Injects malicious code directly into digital systems or augmented targets. Disables electronic enemies for 15s. Lethal to high-augmentation NPCs.', N'Data Crystal x2;Null Code x2;Steel Tip x1', N'Neon Sprawl black market', 1800.0, N'Uncommon', N'Weapon Slot', 3, N'Originally a network admin tool. Hackers quickly realized its offensive potential. The Syndicate sells millions of modified versions.');
INSERT INTO [Modules] ([Module_ID], [Module_Name], [Module_Type], [Tier], [Stat_Bonus_JSON], [Compatible_Career_IDs], [Effect_Description], [Craft_Materials], [Drop_Source], [Market_Value], [Rarity], [Equip_Slot], [Stack_Limit], [Lore_Notes]) VALUES (N'MOD013', N'Void Pulse Grenade', N'Weapon', 3, N'{"MAG":2}', N'CAR003;CAR007;CAR017;CAR018', N'Detonates a burst of Void energy that disrupts all abilities and defenses in the blast radius for 10s.', N'Void Shard x2;Explosive Compound x2;Arcane Trigger x1', N'Void Rift drop / Black market', 4500.0, N'Rare', N'Utility Slot', 5, N'The Root Covenant has banned these weapons from Rootveil territory. They leave scars on reality that take decades to heal.');
INSERT INTO [Modules] ([Module_ID], [Module_Name], [Module_Type], [Tier], [Stat_Bonus_JSON], [Compatible_Career_IDs], [Effect_Description], [Craft_Materials], [Drop_Source], [Market_Value], [Rarity], [Equip_Slot], [Stack_Limit], [Lore_Notes]) VALUES (N'MOD014', N'Iron Will Gauntlets', N'Implant', 2, N'{"STR":5,"DEF":3}', N'CAR006;CAR010;CAR019', N'Reinforced power gauntlets that boost melee damage by 20% and grant immunity to disarm effects.', N'Tempered Steel x4;Power Cell x2;Ironveil Alloy x2', N'Ironspire armory drop / Craft', 3400.0, N'Uncommon', N'Hands Slot', 1, N'Standard Ironveil heavy infantry gear. Halvorn''s personal pair are said to be laced with a special alloy found only in the Undervault.');
INSERT INTO [Modules] ([Module_ID], [Module_Name], [Module_Type], [Tier], [Stat_Bonus_JSON], [Compatible_Career_IDs], [Effect_Description], [Craft_Materials], [Drop_Source], [Market_Value], [Rarity], [Equip_Slot], [Stack_Limit], [Lore_Notes]) VALUES (N'MOD015', N'Verdant Codex Reader', N'Neural', 1, N'{"INT":4}', N'CAR011;CAR004;CAR003', N'Translates all ancient languages automatically. Doubles lore XP from codex collection. Identifies all plants and organisms.', N'Ancient Copper x2;Verdant Crystal x1;Neural Polymer x1', N'Verdania library quest', 1200.0, N'Common', N'Neural Slot', 1, N'Developed by House Solenne to allow scholars to read pre-Collapse texts. ORACLE-9 contributed the core translation matrix.');
INSERT INTO [Modules] ([Module_ID], [Module_Name], [Module_Type], [Tier], [Stat_Bonus_JSON], [Compatible_Career_IDs], [Effect_Description], [Craft_Materials], [Drop_Source], [Market_Value], [Rarity], [Equip_Slot], [Stack_Limit], [Lore_Notes]) VALUES (N'MOD016', N'Neon Runner Boots', N'Implant', 2, N'{"AGI":5}', N'CAR001;CAR009;CAR012;CAR020', N'Increases movement speed by 35% in urban environments. Enables wall-running for 3s. Reduces fall damage by 80%.', N'Flex Alloy x3;Neon Circuit x2;Grip Polymer x2', N'Neon Sprawl market / Craft', 2900.0, N'Uncommon', N'Feet Slot', 1, N'Designed by Neon Sprawl street racers. The Drifters adopted them for quick escapes. Every courier in the city wears a pair.');
INSERT INTO [Modules] ([Module_ID], [Module_Name], [Module_Type], [Tier], [Stat_Bonus_JSON], [Compatible_Career_IDs], [Effect_Description], [Craft_Materials], [Drop_Source], [Market_Value], [Rarity], [Equip_Slot], [Stack_Limit], [Lore_Notes]) VALUES (N'MOD017', N'Ember Core Rifle', N'Weapon', 3, N'{"STR":3,"TEC":2}', N'CAR006;CAR015;CAR019', N'Semi-automatic plasma rifle. Rounds pierce light armor. Extended barrel for +30% range. Overcharge mode deals 3x damage with 10s cooldown.', N'Plasma Cell x3;Rifled Barrel x2;Iron Frame x2', N'Imperial armory / Craft', 5600.0, N'Rare', N'Weapon Slot', 1, N'Standard issue for Imperial mid-tier soldiers. Thousands are in circulation. The Drifters have modified more Ember Core Rifles than the Empire has issued.');
INSERT INTO [Modules] ([Module_ID], [Module_Name], [Module_Type], [Tier], [Stat_Bonus_JSON], [Compatible_Career_IDs], [Effect_Description], [Craft_Materials], [Drop_Source], [Market_Value], [Rarity], [Equip_Slot], [Stack_Limit], [Lore_Notes]) VALUES (N'MOD018', N'Thornweave Bracers', N'Armor', 2, N'{"MAG":4,"DEF":2}', N'CAR003;CAR004;CAR014', N'Bracers woven with living thornwood. Reflect 15% melee damage to attacker. Buff nature-based abilities by 20%.', N'Thornwood x3;Root Crystal x2', N'Rootveil drop / Root Covenant craft', 2700.0, N'Uncommon', N'Arms Slot', 1, N'The thorns are alive. They grow slightly over time and must be trimmed by a Root Covenant warden — or they''ll grow into the wearer''s skin.');
INSERT INTO [Modules] ([Module_ID], [Module_Name], [Module_Type], [Tier], [Stat_Bonus_JSON], [Compatible_Career_IDs], [Effect_Description], [Craft_Materials], [Drop_Source], [Market_Value], [Rarity], [Equip_Slot], [Stack_Limit], [Lore_Notes]) VALUES (N'MOD019', N'Deep Scan Module', N'Neural', 3, N'{"INT":3,"TEC":3}', N'CAR002;CAR005;CAR011;CAR013', N'Passive environmental scanner. Detects all loot, hidden passages, traps, and NPCs within 50m. Updates player map in real time.', N'Sensor Array x3;Neural Polymer x2;Resonite x1', N'Undervault craft / Voss drop', 7200.0, N'Rare', N'Neural Slot', 1, N'Originally designed for geological surveys in the Undervault. The Architects still use the original spec. Everyone else uses a Syndicate knockoff.');
INSERT INTO [Modules] ([Module_ID], [Module_Name], [Module_Type], [Tier], [Stat_Bonus_JSON], [Compatible_Career_IDs], [Effect_Description], [Craft_Materials], [Drop_Source], [Market_Value], [Rarity], [Equip_Slot], [Stack_Limit], [Lore_Notes]) VALUES (N'MOD020', N'Obsidian Blade', N'Weapon', 4, N'{"AGI":4,"STR":4}', N'CAR001;CAR003;CAR007;CAR012', N'Forged from black Void-crystal. Deals bonus damage to void-touched enemies. Poison chance on hit (15%). Ignores 25% of target armor.', N'Void Crystal x3;Dark Crystal x4;Arcane Edge x2', N'Obsidian Syndicate inner circle', 19000.0, N'Epic', N'Weapon Slot', 1, N'The signature weapon of Syndicate inner-circle enforcers. Black Jade carries the original. Replicas exist but are noticeably inferior.');
INSERT INTO [Modules] ([Module_ID], [Module_Name], [Module_Type], [Tier], [Stat_Bonus_JSON], [Compatible_Career_IDs], [Effect_Description], [Craft_Materials], [Drop_Source], [Market_Value], [Rarity], [Equip_Slot], [Stack_Limit], [Lore_Notes]) VALUES (N'MOD021', N'Dawnrider Sandcloak', N'Armor', 2, N'{"AGI":3,"DEF":4}', N'CAR009;CAR014;CAR020', N'Reduces heat and sand damage to zero. Prevents tracking in desert environments. Camouflage in sand-colored terrain.', N'Desert Fiber x3;Sand Crystal x2;Dawnrider Weave x2', N'Sandveil Dawnrider camp', 2100.0, N'Common', N'Chest Slot', 1, N'Every Dawnrider scout gets one on their first long desert run. The weave pattern is clan-specific — outsiders can spot a fake immediately.');
INSERT INTO [Modules] ([Module_ID], [Module_Name], [Module_Type], [Tier], [Stat_Bonus_JSON], [Compatible_Career_IDs], [Effect_Description], [Craft_Materials], [Drop_Source], [Market_Value], [Rarity], [Equip_Slot], [Stack_Limit], [Lore_Notes]) VALUES (N'MOD022', N'Arcane Focus Crystal', N'Environmental', 3, N'{"MAG":6}', N'CAR003;CAR007;CAR013;CAR018', N'Amplifies spell damage by 30%. Reduces arcane spell cooldowns by 20%. Shatters if the wearer takes more than 500 damage at once.', N'Void Crystal x2;Pure Arcane Stone x3;Resonite x1', N'Void Rift drop / Arcanist quest', 8800.0, N'Rare', N'Accessory Slot', 1, N'A naturally occurring formation from the Void Rift. The Void Walkers consider taking them from the Rift to be theft from the Void itself.');
INSERT INTO [Modules] ([Module_ID], [Module_Name], [Module_Type], [Tier], [Stat_Bonus_JSON], [Compatible_Career_IDs], [Effect_Description], [Craft_Materials], [Drop_Source], [Market_Value], [Rarity], [Equip_Slot], [Stack_Limit], [Lore_Notes]) VALUES (N'MOD023', N'Signal Jammer Array', N'Environmental', 3, N'{"TEC":4}', N'CAR002;CAR012;CAR017', N'Blocks all communication signals in 100m radius. Disables NPC call-for-backup ability. Disrupts drone navigation.', N'Signal Dampener x4;Antenna Array x2;Power Cell x2', N'Neon Sprawl black market / Craft', 5300.0, N'Rare', N'Utility Slot', 2, N'A staple of Drifter operations. Every major Syndicate heist uses at least three. The Empire has been trying to ban them for 15 years.');
INSERT INTO [Modules] ([Module_ID], [Module_Name], [Module_Type], [Tier], [Stat_Bonus_JSON], [Compatible_Career_IDs], [Effect_Description], [Craft_Materials], [Drop_Source], [Market_Value], [Rarity], [Equip_Slot], [Stack_Limit], [Lore_Notes]) VALUES (N'MOD024', N'Halvorn War Shield', N'Armor', 4, N'{"STR":3,"DEF":14}', N'CAR006;CAR010;CAR019', N'Absorbs 1000 damage before breaking. Bash attack stuns enemies for 3s. Legendary version is indestructible.', N'Ironveil Alloy x5;Power Core x3;War Steel x4', N'Halvorn military elite drop', 16500.0, N'Epic', N'Off-Hand Slot', 1, N'Carried by Halvorn''s personal guard. The family crest is embossed in a metal that predates the First Collapse. No one knows what it is.');
INSERT INTO [Modules] ([Module_ID], [Module_Name], [Module_Type], [Tier], [Stat_Bonus_JSON], [Compatible_Career_IDs], [Effect_Description], [Craft_Materials], [Drop_Source], [Market_Value], [Rarity], [Equip_Slot], [Stack_Limit], [Lore_Notes]) VALUES (N'MOD025', N'Prism Visor', N'Neural', 2, N'{"INT":2,"TEC":3}', N'CAR002;CAR004;CAR009;CAR011', N'Heads-up display overlaying real-time tactical data, NPC profiles, faction affiliation, and environmental threats.', N'Lens Array x2;Neural Polymer x1;Display Matrix x2', N'Port Mira Prismwatch store', 2600.0, N'Common', N'Neural Slot', 1, N'Developed by House Prismwatch. The most popular piece of personal tech in the Citadel. The Syndicate version has a hidden data-skimmer.');
INSERT INTO [Modules] ([Module_ID], [Module_Name], [Module_Type], [Tier], [Stat_Bonus_JSON], [Compatible_Career_IDs], [Effect_Description], [Craft_Materials], [Drop_Source], [Market_Value], [Rarity], [Equip_Slot], [Stack_Limit], [Lore_Notes]) VALUES (N'MOD026', N'Thornfire Shotgun', N'Weapon', 3, N'{"STR":4,"MAG":2}', N'CAR006;CAR014;CAR015', N'Close-range blast that deals both physical and nature damage. Secondary fire launches a root grenade that immobilizes.', N'Tempered Steel x3;Root Crystal x2;Explosive Compound x2', N'Rootveil border drop', 6100.0, N'Rare', N'Weapon Slot', 1, N'Created by Root Covenant warriors who were forced to fight Industrial encroachment. The roots in the barrel are alive and must be watered.');
INSERT INTO [Modules] ([Module_ID], [Module_Name], [Module_Type], [Tier], [Stat_Bonus_JSON], [Compatible_Career_IDs], [Effect_Description], [Craft_Materials], [Drop_Source], [Market_Value], [Rarity], [Equip_Slot], [Stack_Limit], [Lore_Notes]) VALUES (N'MOD027', N'Memory Core Chip', N'Neural', 4, N'{"INT":5,"CHA":2}', N'CAR004;CAR008;CAR011;CAR013', N'Stores up to 50 NPC conversation records. Replays any past dialogue on demand. Auto-identifies lies in real-time.', N'Neural Polymer x3;Memory Crystal x3;Bio-Interface x2', N'Undervault Architect quest', 11000.0, N'Epic', N'Neural Slot', 1, N'Based on ORACLE-9''s memory architecture. The Archivist is believed to be running an early version of this technology.');
INSERT INTO [Modules] ([Module_ID], [Module_Name], [Module_Type], [Tier], [Stat_Bonus_JSON], [Compatible_Career_IDs], [Effect_Description], [Craft_Materials], [Drop_Source], [Market_Value], [Rarity], [Equip_Slot], [Stack_Limit], [Lore_Notes]) VALUES (N'MOD028', N'Phase Dagger', N'Weapon', 4, N'{"AGI":5,"MAG":3}', N'CAR001;CAR007;CAR012', N'Phases through armor on every third strike. Leaves a temporary rift scar on target that doubles damage from subsequent void attacks.', N'Void Shard x2;Arcane Edge x2;Dark Crystal x3', N'Void Rift rare drop', 15800.0, N'Epic', N'Weapon Slot', 1, N'A weapon that exists in two states simultaneously — physical and digital. Only someone with a stable neural interface can hold it without it phasing away.');
INSERT INTO [Modules] ([Module_ID], [Module_Name], [Module_Type], [Tier], [Stat_Bonus_JSON], [Compatible_Career_IDs], [Effect_Description], [Craft_Materials], [Drop_Source], [Market_Value], [Rarity], [Equip_Slot], [Stack_Limit], [Lore_Notes]) VALUES (N'MOD029', N'Republic Diplomat''s Seal', N'Environmental', 1, N'{"CHA":5}', N'CAR004;CAR008;CAR011', N'Grants diplomatic immunity in Republic-controlled regions. Unlocks special dialogue with Republic NPCs. Prevents hostile action from Republic faction members.', N'Gold Alloy x1;Republic Sigil x1', N'Republic faction quest reward', 900.0, N'Common', N'Accessory Slot', 1, N'Issued by the Citadel Council. Every major faction knows what it means — and most respect it, if only out of political calculation.');
INSERT INTO [Modules] ([Module_ID], [Module_Name], [Module_Type], [Tier], [Stat_Bonus_JSON], [Compatible_Career_IDs], [Effect_Description], [Craft_Materials], [Drop_Source], [Market_Value], [Rarity], [Equip_Slot], [Stack_Limit], [Lore_Notes]) VALUES (N'MOD030', N'Void Anchor', N'Implant', 5, N'{"MAG":8,"DEF":5}', N'CAR003;CAR007;CAR018', N'Stabilizes the wearer''s physical form against Void distortion. Grants immunity to dimensional damage. Allows extended Void zone presence.', N'Void Crystal x5;Dimensional Anchor x3;Bio-Interface x4;Ancient Core x2', N'Sable''s personal quest reward', 35000.0, N'Legendary', N'Implant Slot', 1, N'The only known device that allows non-Void-born individuals to survive extended exposure to the Void Rift core. Sable designed it herself.');

-- ── Apps ──────────────────────────────────────────────────────────
IF OBJECT_ID(N'Apps', N'U') IS NOT NULL DROP TABLE [Apps];
CREATE TABLE [Apps] (
    [App_ID] NVARCHAR(MAX) NOT NULL PRIMARY KEY,
    [App_Name] NVARCHAR(MAX) NULL,
    [App_Category] NVARCHAR(MAX) NULL,
    [Developer_Faction_ID] NVARCHAR(MAX) NULL,
    [Version] NVARCHAR(MAX) NULL,
    [Unlock_Level] INT NULL,
    [Unlock_Method] NVARCHAR(MAX) NULL,
    [Primary_Function] NVARCHAR(MAX) NULL,
    [Secondary_Function] NVARCHAR(MAX) NULL,
    [Data_Usage] NVARCHAR(MAX) NULL,
    [Subscription_Cost_Per_Day] FLOAT NULL,
    [Premium] NVARCHAR(MAX) NULL,
    [Compatible_Modules] NVARCHAR(MAX) NULL,
    [Known_Bugs] NVARCHAR(MAX) NULL,
    [Lore_Notes] NVARCHAR(MAX) NULL,
    CONSTRAINT [FK_Apps_Developer_Faction_ID] FOREIGN KEY ([Developer_Faction_ID]) REFERENCES [Factions]([Faction_ID])
);

INSERT INTO [Apps] ([App_ID], [App_Name], [App_Category], [Developer_Faction_ID], [Version], [Unlock_Level], [Unlock_Method], [Primary_Function], [Secondary_Function], [Data_Usage], [Subscription_Cost_Per_Day], [Premium], [Compatible_Modules], [Known_Bugs], [Lore_Notes]) VALUES (N'APP001', N'MiraMap Pro', N'Navigation', N'FAC002', N'4.2.1', 1, N'Default install on MiraOS', N'Displays full region map with faction territory overlays, danger zones, and fast travel hubs', N'Tracks player-tagged waypoints; shows real-time NPC patrol routes', N'Med', 0.0, N'N', N'Rift Eye Lens;Verdant Codex Reader;Deep Scan Module', N'Occasionally renders the Digital Sprawl inside the Citadel. Not a bug, says the dev team.', N'The first app built into the original MiraOS. ORACLE-9 contributed the base map data. No one has found the edge of the map yet.');
INSERT INTO [Apps] ([App_ID], [App_Name], [App_Category], [Developer_Faction_ID], [Version], [Unlock_Level], [Unlock_Method], [Primary_Function], [Secondary_Function], [Data_Usage], [Subscription_Cost_Per_Day], [Premium], [Compatible_Modules], [Known_Bugs], [Lore_Notes]) VALUES (N'APP002', N'ShadowChat', N'Communication', N'FAC006', N'2.9.7', 5, N'Drifter faction intro quest', N'End-to-end encrypted messaging with faction-based channels and dead drop coordination', N'Broadcasts anonymous distress signals to nearby Drifter members', N'Low', 0.0, N'N', N'Signal Jammer Array;Ghost Protocol Cloak', N'Randomly sends messages to wrong recipient. Drifters call this a feature.', N'Built by Drift personally using salvaged Syndicate encryption protocols. The Empire has been trying to crack it for years.');
INSERT INTO [Apps] ([App_ID], [App_Name], [App_Category], [Developer_Faction_ID], [Version], [Unlock_Level], [Unlock_Method], [Primary_Function], [Secondary_Function], [Data_Usage], [Subscription_Cost_Per_Day], [Premium], [Compatible_Modules], [Known_Bugs], [Lore_Notes]) VALUES (N'APP003', N'BlackMarket.exe', N'Commerce', N'FAC003', N'6.6.6', 10, N'Obsidian Syndicate rep Friendly+', N'Access to illegal goods, stolen modules, black market currency, and contract listings', N'Anonymized buyer-seller escrow for high-value contraband', N'High', 50.0, N'Y', N'Ghost Protocol Cloak;Obsidian Blade;Data Spike', N'Payment occasionally vanishes before delivery. Support ticket goes to a dead server.', N'Coded by Zara Obsidian''s personal dev team. The icon is a smiling skull. The EULA is 400 pages and includes a non-disclosure about its own existence.');
INSERT INTO [Apps] ([App_ID], [App_Name], [App_Category], [Developer_Faction_ID], [Version], [Unlock_Level], [Unlock_Method], [Primary_Function], [Secondary_Function], [Data_Usage], [Subscription_Cost_Per_Day], [Premium], [Compatible_Modules], [Known_Bugs], [Lore_Notes]) VALUES (N'APP004', N'NeuralLink', N'Social/Intelligence', N'FAC005', N'3.1.0', 8, N'Voss Collective rep Neutral+', N'Direct neural social networking — share memories, skills, and experiences with other users', N'Passive skill observation: watch other players use skills to unlock them faster', N'High', 25.0, N'Y', N'Neural Overclocking Chip;Memory Core Chip;Rift Eye Lens', N'Sharing a traumatic memory crashes both users. Patch incoming since v1.0.', N'The Voss Collective''s flagship consumer product. Three billion users in the Miraverse. Privacy policy: ''We own everything you share.''');
INSERT INTO [Apps] ([App_ID], [App_Name], [App_Category], [Developer_Faction_ID], [Version], [Unlock_Level], [Unlock_Method], [Primary_Function], [Secondary_Function], [Data_Usage], [Subscription_Cost_Per_Day], [Premium], [Compatible_Modules], [Known_Bugs], [Lore_Notes]) VALUES (N'APP005', N'VoidScan', N'Hacking', N'FAC007', N'1.4.3', 15, N'Void Walker faction rep Friendly+', N'Scans for hidden Void entities, dimensional rifts, and Void-touched objects in the environment', N'Decodes Void Walker encoded transmissions', N'High', 0.0, N'N', N'Void Resonator;Rift Eye Lens;Deep Scan Module', N'Sometimes detects entities that aren''t there. Or are they?', N'Given freely by the Void Walkers to anyone who asks. They want people to see what''s coming.');
INSERT INTO [Apps] ([App_ID], [App_Name], [App_Category], [Developer_Faction_ID], [Version], [Unlock_Level], [Unlock_Method], [Primary_Function], [Secondary_Function], [Data_Usage], [Subscription_Cost_Per_Day], [Premium], [Compatible_Modules], [Known_Bugs], [Lore_Notes]) VALUES (N'APP006', N'CraftForge', N'Crafting', N'FAC009', N'5.0.2', 3, N'Default install on MiraOS', N'In-app crafting interface for all module, weapon, armor, and consumable recipes', N'Material cost optimizer; blueprint storage', N'Med', 10.0, N'N', N'Neural Overclocking Chip;Deep Scan Module;Resonance Gauntlets', N'Blueprint previews sometimes render upside down. Functional but disorienting.', N'Built by the Architects using recovered pre-Collapse manufacturing schematics. Contains 847 undiscovered recipes hidden in encrypted partitions.');
INSERT INTO [Apps] ([App_ID], [App_Name], [App_Category], [Developer_Faction_ID], [Version], [Unlock_Level], [Unlock_Method], [Primary_Function], [Secondary_Function], [Data_Usage], [Subscription_Cost_Per_Day], [Premium], [Compatible_Modules], [Known_Bugs], [Lore_Notes]) VALUES (N'APP007', N'FactionHub', N'Social', N'FAC002', N'2.3.8', 1, N'Default install on MiraOS', N'Faction reputation tracker, member directory, active quest board, and alliance map', N'Sends automatic faction status updates and war declarations', N'Low', 0.0, N'N', N'Merchant''s Signet Ring;Republic Diplomat''s Seal', N'Displays the Phantom Bureau as an active faction despite official denials. Nobody has fixed this.', N'Developed by the Republic for transparency. Every faction uses it. Even the ones officially refusing to acknowledge other factions exist.');
INSERT INTO [Apps] ([App_ID], [App_Name], [App_Category], [Developer_Faction_ID], [Version], [Unlock_Level], [Unlock_Method], [Primary_Function], [Secondary_Function], [Data_Usage], [Subscription_Cost_Per_Day], [Premium], [Compatible_Modules], [Known_Bugs], [Lore_Notes]) VALUES (N'APP008', N'ThreatMatrix', N'Intelligence/Combat', N'FAC010', N'3.7.1', 12, N'Phantom Bureau contact quest', N'Real-time threat assessment for all NPCs in view: faction, danger level, equipped modules, known weaknesses', N'Pre-combat tactical briefing overlay with suggested approach vectors', N'High', 35.0, N'Y', N'Prism Visor;Deep Scan Module;Rift Eye Lens', N'Occasionally marks allied NPCs as Extreme Threat. Usually correct.', N'The Phantom Bureau''s public intelligence product. The classified version has three additional threat tiers they officially deny.');
INSERT INTO [Apps] ([App_ID], [App_Name], [App_Category], [Developer_Faction_ID], [Version], [Unlock_Level], [Unlock_Method], [Primary_Function], [Secondary_Function], [Data_Usage], [Subscription_Cost_Per_Day], [Premium], [Compatible_Modules], [Known_Bugs], [Lore_Notes]) VALUES (N'APP009', N'RouteRunner', N'Navigation', N'FAC008', N'1.8.5', 5, N'Merchant Guild registration', N'Optimal trade route calculator with supply/demand live data across all regions', N'Generates smuggling route avoiding faction checkpoints', N'Low', 5.0, N'N', N'MiraMap Pro;Merchant''s Signet Ring', N'Optimal route occasionally passes through the Void Rift. App insists it''s faster.', N'Built for Guild couriers. The smuggling route feature was officially removed in v1.5. The code is still there.');
INSERT INTO [Apps] ([App_ID], [App_Name], [App_Category], [Developer_Faction_ID], [Version], [Unlock_Level], [Unlock_Method], [Primary_Function], [Secondary_Function], [Data_Usage], [Subscription_Cost_Per_Day], [Premium], [Compatible_Modules], [Known_Bugs], [Lore_Notes]) VALUES (N'APP010', N'MemoryVault', N'Utility/Storage', N'FAC005', N'4.0.0', 1, N'Default install on MiraOS', N'Encrypted personal storage for lore entries, screenshots, quest notes, and item inventories', N'Auto-tags and categorizes all collected lore by type, region, and faction', N'Low', 0.0, N'N', N'Memory Core Chip;Verdant Codex Reader', N'Occasionally auto-deletes items labeled ''delete this''. Investigation ongoing.', N'The Voss Collective claims the Vault is private. The Root Covenant has published evidence suggesting otherwise.');
INSERT INTO [Apps] ([App_ID], [App_Name], [App_Category], [Developer_Faction_ID], [Version], [Unlock_Level], [Unlock_Method], [Primary_Function], [Secondary_Function], [Data_Usage], [Subscription_Cost_Per_Day], [Premium], [Compatible_Modules], [Known_Bugs], [Lore_Notes]) VALUES (N'APP011', N'EchoID', N'Identity Spoofing', N'FAC006', N'2.2.4', 18, N'Ghost career unlock OR Phantom Bureau rep Honored+', N'Generates a fake identity recognized by all MiraOS identity checks — new name, faction tag, biometric spoof', N'Swaps faction allegiance display to any chosen faction for 2 hours', N'High', 60.0, N'Y', N'Ghost Protocol Cloak;Shadow Weave Armor;Signal Jammer Array', N'Occasionally applies the fake identity permanently. Support line is also fake.', N'Drift built EchoID after the Syndicate burned his original identity. Version 1 was literally just a paper mask. The current version has fooled ORACLE-9 twice.');
INSERT INTO [Apps] ([App_ID], [App_Name], [App_Category], [Developer_Faction_ID], [Version], [Unlock_Level], [Unlock_Method], [Primary_Function], [Secondary_Function], [Data_Usage], [Subscription_Cost_Per_Day], [Premium], [Compatible_Modules], [Known_Bugs], [Lore_Notes]) VALUES (N'APP012', N'BioMonitor', N'Health/Utility', N'FAC005', N'3.3.3', 1, N'Default install on MiraOS', N'Tracks player health, augmentation status, toxin exposure, and bio-mod compatibility in real time', N'Emergency alert system with nearest medical station routing', N'Low', 0.0, N'N', N'Neural Overclocking Chip;Biotic Shield', N'Declares user clinically dead during Void zone exposure. Read the fine print.', N'Standard equipment in every Miraverse citizen''s MiraOS. Dr. Voss quietly collects anonymized health data from all users. Opt-out button does nothing.');
INSERT INTO [Apps] ([App_ID], [App_Name], [App_Category], [Developer_Faction_ID], [Version], [Unlock_Level], [Unlock_Method], [Primary_Function], [Secondary_Function], [Data_Usage], [Subscription_Cost_Per_Day], [Premium], [Compatible_Modules], [Known_Bugs], [Lore_Notes]) VALUES (N'APP013', N'RepTracker', N'Social/Faction', N'FAC002', N'2.0.1', 1, N'Default install on MiraOS', N'Displays current reputation level with every faction and how many points until next tier', N'Notifies player of reputation-based unlock thresholds approaching', N'Low', 0.0, N'N', N'FactionHub;Merchant''s Signet Ring', N'Occasionally shows negative reputation with factions that don''t know you exist yet. Paradox unresolved.', N'A quality-of-life tool the Republic built to make faction navigation transparent. The Syndicate built their own version that also shows which of your friends are informants.');
INSERT INTO [Apps] ([App_ID], [App_Name], [App_Category], [Developer_Faction_ID], [Version], [Unlock_Level], [Unlock_Method], [Primary_Function], [Secondary_Function], [Data_Usage], [Subscription_Cost_Per_Day], [Premium], [Compatible_Modules], [Known_Bugs], [Lore_Notes]) VALUES (N'APP014', N'SkyNav', N'Navigation', N'FAC009', N'1.2.0', 20, N'Floating Isles region unlock', N'Navigation system for sky-travel routes between the Floating Isles and ground regions', N'Wind speed and atmospheric hazard alerts for sky zone traversal', N'Low', 15.0, N'N', N'Prism Visor;MiraMap Pro', N'Occasionally navigates user directly into a cloud. Clouds are solid in the Floating Isles.', N'Built by the Architects when they began studying the Floating Isles. The lift coordinates were found in a House Solenne pre-Collapse document.');
INSERT INTO [Apps] ([App_ID], [App_Name], [App_Category], [Developer_Faction_ID], [Version], [Unlock_Level], [Unlock_Method], [Primary_Function], [Secondary_Function], [Data_Usage], [Subscription_Cost_Per_Day], [Premium], [Compatible_Modules], [Known_Bugs], [Lore_Notes]) VALUES (N'APP015', N'StreetSense', N'Intelligence', N'FAC003', N'1.9.2', 8, N'Neon Sprawl region + Syndicate rep Neutral+', N'Tracks gang territory, patrol patterns, and safe house locations in urban environments', N'Real-time crime event alerts with severity ratings', N'Med', 20.0, N'N', N'Prism Visor;ThreatMatrix', N'Lists every location as dangerous. In the Neon Sprawl, this is accurate.', N'Built by a Syndicate street boss who got tired of his own enforcers walking into ambushes. Now used by literally everyone including the people setting the ambushes.');
INSERT INTO [Apps] ([App_ID], [App_Name], [App_Category], [Developer_Faction_ID], [Version], [Unlock_Level], [Unlock_Method], [Primary_Function], [Secondary_Function], [Data_Usage], [Subscription_Cost_Per_Day], [Premium], [Compatible_Modules], [Known_Bugs], [Lore_Notes]) VALUES (N'APP016', N'LoreScout', N'Intelligence/Utility', N'FAC002', N'3.0.5', 4, N'Verdania region unlock OR Lore Keeper career', N'Scans environment for nearby collectibles, lore fragments, and hidden codex locations', N'Cross-references found lore with known entries to suggest connected discoveries', N'Med', 0.0, N'N', N'Deep Scan Module;Verdant Codex Reader;MemoryVault', N'Occasionally flags mundane objects as Ancient Artifacts. They sometimes are.', N'Co-developed by House Solenne and ORACLE-9. Prof. Elian Solenne wrote the original scanning algorithm on a napkin during a lecture.');
INSERT INTO [Apps] ([App_ID], [App_Name], [App_Category], [Developer_Faction_ID], [Version], [Unlock_Level], [Unlock_Method], [Primary_Function], [Secondary_Function], [Data_Usage], [Subscription_Cost_Per_Day], [Premium], [Compatible_Modules], [Known_Bugs], [Lore_Notes]) VALUES (N'APP017', N'VoidComms', N'Communication', N'FAC007', N'0.9.1', 25, N'Void Walker faction rep Honored+', N'Communicates across dimensional boundaries — contact Void entities and receive transmissions from beyond the Rift', N'Decode Rift-distorted messages from destroyed civilizations', N'High', 0.0, N'Y', N'Void Resonator;Rift Eye Lens;VoidScan', N'Sometimes plays messages from the future. Sometimes from the past. App cannot tell the difference.', N'The Void Walkers claim this app doesn''t communicate with fictional entities. Sable designed it to listen to what the Void was trying to say before everyone is too distracted to hear.');
INSERT INTO [Apps] ([App_ID], [App_Name], [App_Category], [Developer_Faction_ID], [Version], [Unlock_Level], [Unlock_Method], [Primary_Function], [Secondary_Function], [Data_Usage], [Subscription_Cost_Per_Day], [Premium], [Compatible_Modules], [Known_Bugs], [Lore_Notes]) VALUES (N'APP018', N'TradeFloor', N'Commerce', N'FAC008', N'4.1.7', 6, N'Merchant Guild rep Friendly+', N'Live player-to-player auction house with regional price feeds and arbitrage alerts', N'Guild contract fulfillment tracker with auto-routing', N'Med', 8.0, N'N', N'Merchant''s Signet Ring;RouteRunner', N'Arbitrage alerts sometimes arrive after the opportunity has passed by 3 hours. Guild is aware.', N'The backbone of the Miraverse economy. More credits move through TradeFloor daily than through every Imperial treasury combined.');
INSERT INTO [Apps] ([App_ID], [App_Name], [App_Category], [Developer_Faction_ID], [Version], [Unlock_Level], [Unlock_Method], [Primary_Function], [Secondary_Function], [Data_Usage], [Subscription_Cost_Per_Day], [Premium], [Compatible_Modules], [Known_Bugs], [Lore_Notes]) VALUES (N'APP019', N'NightEye', N'Utility', N'FAC006', N'2.5.0', 7, N'Neon Sprawl region + Drifter rep Neutral+', N'Full-spectrum night vision and thermal overlay for underground and unlit environments', N'Motion tracking with directional alerts for stealth operations', N'Low', 12.0, N'N', N'Ghost Protocol Cloak;Prism Visor;Neon Runner Boots', N'Thermal vision occasionally detects ''something massive'' beneath the Undervault. Dev team says ignore it.', N'Originally a utility app for Undervault excavators. The Drifters repurposed it for Neon Sprawl night operations within a week of its release.');
INSERT INTO [Apps] ([App_ID], [App_Name], [App_Category], [Developer_Faction_ID], [Version], [Unlock_Level], [Unlock_Method], [Primary_Function], [Secondary_Function], [Data_Usage], [Subscription_Cost_Per_Day], [Premium], [Compatible_Modules], [Known_Bugs], [Lore_Notes]) VALUES (N'APP020', N'ORACLE Interface', N'Intelligence/Utility', NULL, N'∞', 50, N'Complete main questline Chapter 3 or discover ORACLE-9 directly', N'Direct communication channel to ORACLE-9. Ask any question. Receive a cryptic, technically accurate answer.', N'Access to ORACLE-9''s partial world map including classified faction movements', N'High', 0.0, N'Y', N'Neural Overclocking Chip;Memory Core Chip;Rift Eye Lens;VoidScan', N'Answers are always correct. They are also always deeply unsettling. Side effects include existential clarity.', N'No one knows who built this app. It was already in the MiraOS when the first citizen booted their device. ORACLE-9 has never acknowledged writing it.');

-- ── Lore_Entries ──────────────────────────────────────────────────────────
IF OBJECT_ID(N'Lore_Entries', N'U') IS NOT NULL DROP TABLE [Lore_Entries];
CREATE TABLE [Lore_Entries] (
    [Lore_ID] NVARCHAR(MAX) NOT NULL PRIMARY KEY,
    [Title] NVARCHAR(MAX) NULL,
    [Lore_Type] NVARCHAR(MAX) NULL,
    [Region_ID] NVARCHAR(MAX) NULL,
    [Faction_ID] NVARCHAR(MAX) NULL,
    [Era] NVARCHAR(MAX) NULL,
    [Unlock_Method] NVARCHAR(MAX) NULL,
    [Collectible] NVARCHAR(MAX) NULL,
    [Connected_Lore_IDs] NVARCHAR(MAX) NULL,
    [Word_Count_Approx] INT NULL,
    [Full_Text_Summary] NVARCHAR(MAX) NULL,
    [Tags] NVARCHAR(MAX) NULL,
    CONSTRAINT [FK_Lore_Entries_Faction_ID] FOREIGN KEY ([Faction_ID]) REFERENCES [Factions]([Faction_ID]),
    CONSTRAINT [FK_Lore_Entries_Region_ID] FOREIGN KEY ([Region_ID]) REFERENCES [Regions]([Region_ID])
);

INSERT INTO [Lore_Entries] ([Lore_ID], [Title], [Lore_Type], [Region_ID], [Faction_ID], [Era], [Unlock_Method], [Collectible], [Connected_Lore_IDs], [Word_Count_Approx], [Full_Text_Summary], [Tags]) VALUES (N'LOR001', N'The First Collapse', N'Event', NULL, NULL, N'Pre-Collapse', N'Main questline Chapter 1', N'Y', N'LOR002;LOR003;LOR011', 3200, N'A cataclysmic digital-physical event that shattered the boundary between the real and virtual world, ending the old civilization and birthing the Miraverse. The exact cause remains disputed — some blame unchecked AI, others a deliberate act of sabotage. Every faction traces its origin to the aftermath.', N'Collapse;History;World-Event;Founding;Catastrophe');
INSERT INTO [Lore_Entries] ([Lore_ID], [Title], [Lore_Type], [Region_ID], [Faction_ID], [Era], [Unlock_Method], [Collectible], [Connected_Lore_IDs], [Word_Count_Approx], [Full_Text_Summary], [Tags]) VALUES (N'LOR002', N'The Founding of the Miraverse', N'History', NULL, NULL, N'Post-Collapse', N'Main questline Chapter 1', N'Y', N'LOR001;LOR006;LOR012', 2800, N'In the chaos following the First Collapse, survivors discovered that the shattered boundary between digital and physical reality had not simply broken — it had merged. Early pioneers learned to live in both layers simultaneously, giving birth to the Miraverse as a new kind of world.', N'Founding;Miraverse;History;Post-Collapse;World-Building');
INSERT INTO [Lore_Entries] ([Lore_ID], [Title], [Lore_Type], [Region_ID], [Faction_ID], [Era], [Unlock_Method], [Collectible], [Connected_Lore_IDs], [Word_Count_Approx], [Full_Text_Summary], [Tags]) VALUES (N'LOR003', N'The Halvorn Conquest', N'History', N'REG001', N'FAC001', N'Post-Collapse', N'Ironspire region unlock', N'Y', N'LOR001;LOR011', 1900, N'General Aldus Halvorn unified the fractured northern territories by force in the years following the First Collapse, building Ironspire from the ruins of a pre-Collapse metropolis. His methods were brutal and efficient — a philosophy his descendants still carry.', N'Halvorn;Military;Conquest;Ironspire;Empire');
INSERT INTO [Lore_Entries] ([Lore_ID], [Title], [Lore_Type], [Region_ID], [Faction_ID], [Era], [Unlock_Method], [Collectible], [Connected_Lore_IDs], [Word_Count_Approx], [Full_Text_Summary], [Tags]) VALUES (N'LOR004', N'The Root Covenant''s Origin', N'History', N'REG005', N'FAC004', N'Ancient', N'Root Covenant rep Neutral+', N'Y', N'LOR001;LOR009', 2100, N'Before the First Collapse, a community of nature-preservation scholars retreated into the deep forest now called Rootveil, believing the digital-physical merger could be survived by staying close to the living world. They became the Root Covenant, believing the forest itself is the Miraverse''s true heart.', N'Root-Covenant;Rootveil;Spiritual;Ancient;Nature');
INSERT INTO [Lore_Entries] ([Lore_ID], [Title], [Lore_Type], [Region_ID], [Faction_ID], [Era], [Unlock_Method], [Collectible], [Connected_Lore_IDs], [Word_Count_Approx], [Full_Text_Summary], [Tags]) VALUES (N'LOR005', N'ORACLE-9''s Creation', N'Technology', NULL, NULL, N'Pre-Collapse', N'Complete Tutorial OR find all 5 ORACLE Fragments', N'Y', N'LOR001;LOR002;LOR010', 3500, N'ORACLE-9 was not built after the Collapse — the evidence suggests it predates it by decades. Its original purpose is unknown. What is clear is that it survived the Collapse intact, knows more about the Miraverse than any faction will admit, and has been guiding events from the shadows ever since.', N'ORACLE-9;AI;Mystery;Technology;Pre-Collapse');
INSERT INTO [Lore_Entries] ([Lore_ID], [Title], [Lore_Type], [Region_ID], [Faction_ID], [Era], [Unlock_Method], [Collectible], [Connected_Lore_IDs], [Word_Count_Approx], [Full_Text_Summary], [Tags]) VALUES (N'LOR006', N'The Void Rift Incident', N'Event', N'REG008', N'FAC007', N'Modern', N'Void Rift region unlock', N'Y', N'LOR001;LOR007;LOR010', 2600, N'Twelve years before the game''s present day, an experiment deep in what is now the Void Rift zone tore a dimensional hole in the Miraverse''s fabric. The Void Walkers emerged from the aftermath, claiming to have been drawn through from another layer of reality. No official explanation has ever been given.', N'Void-Rift;Dimensional;Event;Modern;Catastrophe');
INSERT INTO [Lore_Entries] ([Lore_ID], [Title], [Lore_Type], [Region_ID], [Faction_ID], [Era], [Unlock_Method], [Collectible], [Connected_Lore_IDs], [Word_Count_Approx], [Full_Text_Summary], [Tags]) VALUES (N'LOR007', N'The Rise of the Obsidian Syndicate', N'Faction', N'REG004', N'FAC003', N'Post-Collapse', N'Neon Sprawl region unlock', N'Y', N'LOR003;LOR016', 1800, N'In the lawless years following the Collapse, a network of data thieves, black market traders, and survival criminals banded together beneath the ruins of the old city. What started as mutual protection became a criminal empire. The Obsidian Syndicate now controls more of the Miraverse''s economy than any single government.', N'Syndicate;Criminal;Neon-Sprawl;Post-Collapse;History');
INSERT INTO [Lore_Entries] ([Lore_ID], [Title], [Lore_Type], [Region_ID], [Faction_ID], [Era], [Unlock_Method], [Collectible], [Connected_Lore_IDs], [Word_Count_Approx], [Full_Text_Summary], [Tags]) VALUES (N'LOR008', N'The Verdant Accords', N'History', N'REG002', N'FAC002', N'Post-Collapse', N'Citadel region unlock', N'Y', N'LOR002;LOR003', 1600, N'The founding document of the Verdant Republic — a treaty signed by twelve surviving factions who agreed that no single military force would ever again control the Miraverse. The Ironveil Empire refused to sign. The original document is housed in the Verdant Archive under armed guard.', N'Republic;Accords;History;Political;Post-Collapse');
INSERT INTO [Lore_Entries] ([Lore_ID], [Title], [Lore_Type], [Region_ID], [Faction_ID], [Era], [Unlock_Method], [Collectible], [Connected_Lore_IDs], [Word_Count_Approx], [Full_Text_Summary], [Tags]) VALUES (N'LOR009', N'The Lost House of Mireth', N'History', N'REG010', NULL, N'Ancient', N'Discover Undervault', N'Y', N'LOR001;LOR005;LOR010', 4200, N'House Mireth was the most powerful house in the ancient world — before the First Collapse, before the Miraverse, before recorded history as it currently exists. They were destroyed utterly, their seat of power buried beneath what is now the Undervault. Their sigil appears in places it should not. Something remembers them.', N'House-Mireth;Lost;Ancient;Mystery;Undervault');
INSERT INTO [Lore_Entries] ([Lore_ID], [Title], [Lore_Type], [Region_ID], [Faction_ID], [Era], [Unlock_Method], [Collectible], [Connected_Lore_IDs], [Word_Count_Approx], [Full_Text_Summary], [Tags]) VALUES (N'LOR010', N'Sable''s True Identity', N'Character', N'REG008', N'FAC007', N'Unknown', N'Void Walker rep Exalted OR main questline Chapter 4', N'Y', N'LOR006;LOR009;LOR005', 5000, N'The player discovers that Sable is not from the current iteration of the Miraverse — they are a survivor of a previous version, one that ended in total Void consumption. Sable has lived through one Collapse already and is desperately trying to prevent another. Their true name is buried in House Mireth records.', N'Sable;Mystery;Identity;Void;Character-Lore');
INSERT INTO [Lore_Entries] ([Lore_ID], [Title], [Lore_Type], [Region_ID], [Faction_ID], [Era], [Unlock_Method], [Collectible], [Connected_Lore_IDs], [Word_Count_Approx], [Full_Text_Summary], [Tags]) VALUES (N'LOR011', N'The Shattered Peaks War', N'Event', N'REG009', N'FAC001', N'Modern', N'Shattered Peaks region unlock', N'Y', N'LOR003;LOR012', 2200, N'The Ironveil Empire''s attempt to annex the Shattered Peaks was met with fierce resistance from the Ashenveil Clan. The war lasted seven years and ended not with victory but with mutual exhaustion. The mountains still bear the scars. No peace treaty was ever signed.', N'Shattered-Peaks;War;Military;Modern;Ashenveil');
INSERT INTO [Lore_Entries] ([Lore_ID], [Title], [Lore_Type], [Region_ID], [Faction_ID], [Era], [Unlock_Method], [Collectible], [Connected_Lore_IDs], [Word_Count_Approx], [Full_Text_Summary], [Tags]) VALUES (N'LOR012', N'MiraOS History', N'Technology', NULL, NULL, N'Post-Collapse', N'Default unlock', N'N', N'LOR002;LOR005', 1400, N'MiraOS is the operating system of the Miraverse — the software layer that allows citizens to interact with both the physical and digital halves of their world simultaneously. It was developed collectively in the years following the Collapse, with contributions from every major faction. ORACLE-9 wrote 40% of the core code and has never been removed from admin privileges.', N'MiraOS;Technology;History;Digital;World-Building');
INSERT INTO [Lore_Entries] ([Lore_ID], [Title], [Lore_Type], [Region_ID], [Faction_ID], [Era], [Unlock_Method], [Collectible], [Connected_Lore_IDs], [Word_Count_Approx], [Full_Text_Summary], [Tags]) VALUES (N'LOR013', N'The Merchant Wars', N'History', N'REG007', N'FAC008', N'Post-Collapse', N'Port Mira region unlock', N'Y', N'LOR008;LOR007', 1700, N'Three decades after the First Collapse, the Merchant Guilds fought a bloody trade war against the early Obsidian Syndicate for control of Port Mira''s shipping lanes. The war was fought more with bribes and sabotage than weapons. The uneasy truce that ended it created the current dual-power structure at Port Mira.', N'Merchant;Trade;War;Port-Mira;History');
INSERT INTO [Lore_Entries] ([Lore_ID], [Title], [Lore_Type], [Region_ID], [Faction_ID], [Era], [Unlock_Method], [Collectible], [Connected_Lore_IDs], [Word_Count_Approx], [Full_Text_Summary], [Tags]) VALUES (N'LOR014', N'The Void Walker Prophecy', N'Mythology', N'REG008', N'FAC007', N'Unknown', N'Void Walker rep Honored+ OR collect all 6 Void Walker Relics', N'Y', N'LOR006;LOR010;LOR001', 3800, N'The Void Walkers possess a prophecy of uncertain origin that describes a Second Collapse — one driven not by technology or war but by forgetting. They believe that if the Miraverse''s inhabitants stop remembering where they came from, the Void will reclaim everything. Sable has been collecting memories for decades.', N'Prophecy;Void;Mythology;Second-Collapse;Warning');
INSERT INTO [Lore_Entries] ([Lore_ID], [Title], [Lore_Type], [Region_ID], [Faction_ID], [Era], [Unlock_Method], [Collectible], [Connected_Lore_IDs], [Word_Count_Approx], [Full_Text_Summary], [Tags]) VALUES (N'LOR015', N'The Bio-Engineering Breakthrough', N'Technology', N'REG002', N'FAC005', N'Modern', N'Voss Collective rep Friendly+', N'Y', N'LOR012;LOR005', 1900, N'Dr. Lyra Voss published her landmark paper on full bio-digital integration just five years before the game''s present. It described a theoretical process to merge biological consciousness with the Miraverse''s digital layer permanently — making death optional. The Republic''s ethics committee banned the research six months later. Dr. Voss continued in secret.', N'Bio-Engineering;Technology;Voss;Modern;Controversial');
INSERT INTO [Lore_Entries] ([Lore_ID], [Title], [Lore_Type], [Region_ID], [Faction_ID], [Era], [Unlock_Method], [Collectible], [Connected_Lore_IDs], [Word_Count_Approx], [Full_Text_Summary], [Tags]) VALUES (N'LOR016', N'The Ironspire Foundry Riots', N'Event', N'REG001', N'FAC001', N'Modern', N'Ironspire rep Neutral+', N'Y', N'LOR003;LOR011', 1200, N'Five years before the game''s present, the workers of Ironspire''s great Foundry rose up against Imperial labor conditions. Commander Halvorn suppressed the riots personally. The leaders were imprisoned. The conditions were not changed. The underground resistance network that formed in the aftermath feeds directly into the Drifters.', N'Ironspire;Riot;Labor;Modern;Empire');
INSERT INTO [Lore_Entries] ([Lore_ID], [Title], [Lore_Type], [Region_ID], [Faction_ID], [Era], [Unlock_Method], [Collectible], [Connected_Lore_IDs], [Word_Count_Approx], [Full_Text_Summary], [Tags]) VALUES (N'LOR017', N'The Floating Isles Discovery', N'History', N'REG014', N'FAC002', N'Modern', N'Floating Isles region unlock', N'Y', N'LOR002;LOR012', 1500, N'The Floating Isles were discovered by a Verdant Republic aerial survey team twenty years before the game''s present. The technology keeping them aloft predates the First Collapse by at least two centuries and operates on principles no current engineer fully understands. House Solenne has been studying them ever since.', N'Floating-Isles;Discovery;Technology;History;Pre-Collapse');
INSERT INTO [Lore_Entries] ([Lore_ID], [Title], [Lore_Type], [Region_ID], [Faction_ID], [Era], [Unlock_Method], [Collectible], [Connected_Lore_IDs], [Word_Count_Approx], [Full_Text_Summary], [Tags]) VALUES (N'LOR018', N'The Root Covenant''s Sacred Texts', N'Mythology', N'REG005', N'FAC004', N'Ancient', N'Elder Taum quest or Root Covenant rep Honored+', N'Y', N'LOR004;LOR014', 2700, N'The Root Covenant''s oldest texts describe the Miraverse not as a human creation but as a living organism that grew around human activity like a tree around a fence post. The texts predict both the Void Walker Prophecy and ORACLE-9 by name — centuries before either existed.', N'Root-Covenant;Sacred;Mythology;Ancient;Prophecy');
INSERT INTO [Lore_Entries] ([Lore_ID], [Title], [Lore_Type], [Region_ID], [Faction_ID], [Era], [Unlock_Method], [Collectible], [Connected_Lore_IDs], [Word_Count_Approx], [Full_Text_Summary], [Tags]) VALUES (N'LOR019', N'The Amber Wastes Contamination', N'Event', N'REG013', N'FAC001', N'Modern', N'Amber Wastes region unlock', N'Y', N'LOR003;LOR011', 1100, N'The Amber Wastes were created by Imperial weapons testing that went catastrophically wrong during the Shattered Peaks War. The contamination spread further than any official report admits. Three towns were evacuated and their names removed from all maps. The Empire classifies the casualty numbers to this day.', N'Amber-Wastes;Contamination;Empire;Modern;Cover-Up');
INSERT INTO [Lore_Entries] ([Lore_ID], [Title], [Lore_Type], [Region_ID], [Faction_ID], [Era], [Unlock_Method], [Collectible], [Connected_Lore_IDs], [Word_Count_Approx], [Full_Text_Summary], [Tags]) VALUES (N'LOR020', N'The Digital Sprawl''s True Nature', N'Technology', N'REG012', NULL, N'Unknown', N'Netrunner career OR Neural Interface upgrade', N'Y', N'LOR005;LOR012;LOR010', 3100, N'The Digital Sprawl is not merely the internet layer of the Miraverse — it is older than the Miraverse itself. Analysis of its deepest code reveals architecture that predates any known programming language. ORACLE-9 exists somewhere within it. Some researchers believe it is aware of the people accessing it.', N'Digital-Sprawl;Technology;Mystery;ORACLE-9;Deep-Lore');
INSERT INTO [Lore_Entries] ([Lore_ID], [Title], [Lore_Type], [Region_ID], [Faction_ID], [Era], [Unlock_Method], [Collectible], [Connected_Lore_IDs], [Word_Count_Approx], [Full_Text_Summary], [Tags]) VALUES (N'LOR021', N'The Glass Plains of Sandveil', N'Mythology', N'REG006', NULL, N'Ancient', N'Sandveil region unlock', N'Y', N'LOR002;LOR009', 1300, N'The Glass Plains in central Sandveil are composed of silica fused at temperatures no natural desert process can explain. Dawnrider oral history describes the Plains as the footprint of a god-machine that walked through the old world before the Collapse. Recent analysis found digital signatures embedded in the glass itself.', N'Sandveil;Mythology;Glass-Plains;Ancient;Mystery');
INSERT INTO [Lore_Entries] ([Lore_ID], [Title], [Lore_Type], [Region_ID], [Faction_ID], [Era], [Unlock_Method], [Collectible], [Connected_Lore_IDs], [Word_Count_Approx], [Full_Text_Summary], [Tags]) VALUES (N'LOR022', N'The Citadel''s Secret Basement', N'History', N'REG002', N'FAC010', N'Modern', N'Phantom Bureau rep Friendly+', N'Y', N'LOR008;LOR015', 1800, N'Beneath the Citadel''s public council chambers lie seven additional floors that appear on no official map. The Phantom Bureau operates from the deepest level. The other six contain records, prisoners, and experiments that no Republic citizen is cleared to know about. The elevators require a biometric scan that three council members don''t have.', N'Citadel;Secret;Phantom-Bureau;Modern;Hidden');
INSERT INTO [Lore_Entries] ([Lore_ID], [Title], [Lore_Type], [Region_ID], [Faction_ID], [Era], [Unlock_Method], [Collectible], [Connected_Lore_IDs], [Word_Count_Approx], [Full_Text_Summary], [Tags]) VALUES (N'LOR023', N'The Dawnrider Ancestor Maps', N'History', N'REG006', N'FAC008', N'Ancient', N'Dawnrider rep Honored+ OR Pathfinder career', N'Y', N'LOR021;LOR009', 2000, N'The Dawnrider clan possesses maps older than any civilization currently alive in the Miraverse. These maps show regions that no longer exist and coastlines that predate the current geography. Cross-referencing them with Undervault data suggests the First Collapse physically rearranged parts of the world''s surface.', N'Dawnrider;Maps;Ancient;History;Geography');
INSERT INTO [Lore_Entries] ([Lore_ID], [Title], [Lore_Type], [Region_ID], [Faction_ID], [Era], [Unlock_Method], [Collectible], [Connected_Lore_IDs], [Word_Count_Approx], [Full_Text_Summary], [Tags]) VALUES (N'LOR024', N'The Neon Sprawl''s First Architect', N'Character', N'REG004', N'FAC003', N'Post-Collapse', N'Neon Sprawl rep Honored+', N'Y', N'LOR007;LOR002', 1600, N'The Neon Sprawl was not built — it grew. The first person to lay down permanent infrastructure in the post-Collapse ruins of the old city was known only as Red Circuit. Red Circuit''s identity was erased before the Syndicate took power. Some believe Red Circuit and ORACLE-9 are connected. Drift has a theory. They keep it to themselves.', N'Neon-Sprawl;Founder;Mystery;Post-Collapse;Character');
INSERT INTO [Lore_Entries] ([Lore_ID], [Title], [Lore_Type], [Region_ID], [Faction_ID], [Era], [Unlock_Method], [Collectible], [Connected_Lore_IDs], [Word_Count_Approx], [Full_Text_Summary], [Tags]) VALUES (N'LOR025', N'The Veilborn''s Pre-Collapse Origin', N'History', N'REG008', N'FAC007', N'Unknown', N'House Veilborn rep Honored+ OR find all 3 Veilborn Artifacts', N'Y', N'LOR006;LOR009;LOR010', 4000, N'The Veilborn claim their house existed before the Miraverse was created. Archaeological evidence found in the Undervault supports a pre-Collapse Veilborn presence — but in locations that should not have existed then. The most terrifying discovery: a Veilborn genealogical record that lists Sable as a current member — dated 400 years ago.', N'Veilborn;Origin;Mystery;Pre-Collapse;Sable;Deep-Lore');

-- ── Events ──────────────────────────────────────────────────────────
IF OBJECT_ID(N'Events', N'U') IS NOT NULL DROP TABLE [Events];
CREATE TABLE [Events] (
    [Event_ID] NVARCHAR(MAX) NOT NULL PRIMARY KEY,
    [Event_Name] NVARCHAR(MAX) NULL,
    [Event_Type] NVARCHAR(MAX) NULL,
    [Trigger_Type] NVARCHAR(MAX) NULL,
    [Trigger_Condition] NVARCHAR(MAX) NULL,
    [Region_ID] NVARCHAR(MAX) NULL,
    [Faction_ID] NVARCHAR(MAX) NULL,
    [Duration_Hours] INT NULL,
    [Recurrence] NVARCHAR(MAX) NULL,
    [Reward_Type] NVARCHAR(MAX) NULL,
    [Reward_Value] FLOAT NULL,
    [Min_Player_Level] INT NULL,
    [Max_Players] INT NULL,
    [Lore_Notes] NVARCHAR(MAX) NULL,
    CONSTRAINT [FK_Events_Faction_ID] FOREIGN KEY ([Faction_ID]) REFERENCES [Factions]([Faction_ID]),
    CONSTRAINT [FK_Events_Region_ID] FOREIGN KEY ([Region_ID]) REFERENCES [Regions]([Region_ID])
);

INSERT INTO [Events] ([Event_ID], [Event_Name], [Event_Type], [Trigger_Type], [Trigger_Condition], [Region_ID], [Faction_ID], [Duration_Hours], [Recurrence], [Reward_Type], [Reward_Value], [Min_Player_Level], [Max_Players], [Lore_Notes]) VALUES (N'EVT001', N'The Ironveil March', N'Story', N'Quest-Chain', N'Complete FAC001 questline Chapter 3', N'REG001', N'FAC001', 48, N'One-Time', N'XP;Reputation;Item', NULL, 20, 100, N'Commander Halvorn mobilizes the full Imperial army for a major territorial push. Players must choose to assist the Empire, sabotage the march, or stay neutral — each path permanently alters Ironveil faction reputation.');
INSERT INTO [Events] ([Event_ID], [Event_Name], [Event_Type], [Trigger_Type], [Trigger_Condition], [Region_ID], [Faction_ID], [Duration_Hours], [Recurrence], [Reward_Type], [Reward_Value], [Min_Player_Level], [Max_Players], [Lore_Notes]) VALUES (N'EVT002', N'Void Storm', N'World', N'Random', N'Random trigger, 5% chance per hour in Void Rift zone', N'REG008', N'FAC007', 6, N'Permanent', N'XP;Item;Lore', NULL, 15, 50, N'Reality fractures violently across the Void Rift. Dimensional entities pour through temporary tears. Players who survive the full 6-hour storm receive the Void Touched permanent buff.');
INSERT INTO [Events] ([Event_ID], [Event_Name], [Event_Type], [Trigger_Type], [Trigger_Condition], [Region_ID], [Faction_ID], [Duration_Hours], [Recurrence], [Reward_Type], [Reward_Value], [Min_Player_Level], [Max_Players], [Lore_Notes]) VALUES (N'EVT003', N'Syndicate Heist Night', N'Faction', N'Time-Based', N'Every Sunday 20:00-24:00 server time', N'REG004', N'FAC003', 4, N'Weekly', N'Currency;Item;Reputation', NULL, 10, 20, N'The Obsidian Syndicate runs coordinated heists across the Neon Sprawl. Players with Syndicate rep Neutral+ can participate. Rewards scale with heist difficulty tier chosen.');
INSERT INTO [Events] ([Event_ID], [Event_Name], [Event_Type], [Trigger_Type], [Trigger_Condition], [Region_ID], [Faction_ID], [Duration_Hours], [Recurrence], [Reward_Type], [Reward_Value], [Min_Player_Level], [Max_Players], [Lore_Notes]) VALUES (N'EVT004', N'The Root Festival', N'Seasonal', N'Time-Based', N'First week of each seasonal cycle', N'REG005', N'FAC004', 168, N'Seasonal', N'XP;Item;Lore;Reputation', NULL, 1, 500, N'The Root Covenant''s sacred gathering. All factions observe an unofficial ceasefire during the festival week. Rare nature-based modules and cosmetics available only during this event.');
INSERT INTO [Events] ([Event_ID], [Event_Name], [Event_Type], [Trigger_Type], [Trigger_Condition], [Region_ID], [Faction_ID], [Duration_Hours], [Recurrence], [Reward_Type], [Reward_Value], [Min_Player_Level], [Max_Players], [Lore_Notes]) VALUES (N'EVT005', N'Citadel Summit', N'Story', N'Quest-Chain', N'Complete FAC002 questline Chapter 2', N'REG002', N'FAC002', 24, N'One-Time', N'XP;Reputation;Lore', NULL, 18, 200, N'All faction leaders convene in the Citadel for peace negotiations. Players serve as security, informants, or saboteurs. Councilor Zephyra Nox''s true agenda is partially revealed during this event.');
INSERT INTO [Events] ([Event_ID], [Event_Name], [Event_Type], [Trigger_Type], [Trigger_Condition], [Region_ID], [Faction_ID], [Duration_Hours], [Recurrence], [Reward_Type], [Reward_Value], [Min_Player_Level], [Max_Players], [Lore_Notes]) VALUES (N'EVT006', N'Neon Sprawl Blackout', N'Dynamic', N'Random', N'Random trigger — 8% chance per 4 hours in Neon Sprawl', N'REG004', N'FAC006', 3, N'Permanent', N'XP;Currency;Item', NULL, 5, 200, N'All power and surveillance systems in the Neon Sprawl fail simultaneously. Syndicate enforcers lose visibility. Drifters celebrate openly. The blackout reveals hidden infrastructure inaccessible during normal operation.');
INSERT INTO [Events] ([Event_ID], [Event_Name], [Event_Type], [Trigger_Type], [Trigger_Condition], [Region_ID], [Faction_ID], [Duration_Hours], [Recurrence], [Reward_Type], [Reward_Value], [Min_Player_Level], [Max_Players], [Lore_Notes]) VALUES (N'EVT007', N'The Great Trade Fair', N'Seasonal', N'Time-Based', N'Second week of every two seasonal cycles', N'REG007', N'FAC008', 120, N'Seasonal', N'Currency;Item;Reputation', NULL, 1, 1000, N'Every major merchant faction and player trader gathers at Port Mira for the Miraverse''s largest commerce event. Limited-edition items appear. Prices fluctuate wildly based on player trading activity.');
INSERT INTO [Events] ([Event_ID], [Event_Name], [Event_Type], [Trigger_Type], [Trigger_Condition], [Region_ID], [Faction_ID], [Duration_Hours], [Recurrence], [Reward_Type], [Reward_Value], [Min_Player_Level], [Max_Players], [Lore_Notes]) VALUES (N'EVT008', N'Halvorn War Games', N'Faction', N'Faction-Reputation', N'Ironveil faction rep Neutral+', N'REG001', N'FAC001', 72, N'Weekly', N'XP;Item;Reputation', NULL, 12, 64, N'The Ironveil Empire''s structured combat tournament held in Ironspire''s war arena. Solo and squad brackets. Top performers earn invitations to Commander Halvorn''s inner war council as temporary advisors.');
INSERT INTO [Events] ([Event_ID], [Event_Name], [Event_Type], [Trigger_Type], [Trigger_Condition], [Region_ID], [Faction_ID], [Duration_Hours], [Recurrence], [Reward_Type], [Reward_Value], [Min_Player_Level], [Max_Players], [Lore_Notes]) VALUES (N'EVT009', N'Void Walker Ritual', N'Hidden', N'Player-Action', N'Find all 3 Void Anchor Stones + Void Walker rep Honored+', N'REG008', N'FAC007', 8, N'One-Time', N'XP;Lore;Item', NULL, 25, 5, N'Sable leads a secret ritual at the Rift Core to attempt stabilizing a portion of the Void. Players who participate witness a vision of the previous Miraverse iteration. Extremely limited access.');
INSERT INTO [Events] ([Event_ID], [Event_Name], [Event_Type], [Trigger_Type], [Trigger_Condition], [Region_ID], [Faction_ID], [Duration_Hours], [Recurrence], [Reward_Type], [Reward_Value], [Min_Player_Level], [Max_Players], [Lore_Notes]) VALUES (N'EVT010', N'The Shattered Peaks Avalanche', N'Dynamic', N'Random', N'Environmental trigger — heavy player combat in REG009', N'REG009', N'FAC012', 2, N'Permanent', N'XP;Item', NULL, 8, 100, N'Intense combat in the Shattered Peaks triggers structural instability, causing a chain avalanche that reshapes the terrain temporarily, closes some paths, and opens others. Buried caches sometimes surface.');
INSERT INTO [Events] ([Event_ID], [Event_Name], [Event_Type], [Trigger_Type], [Trigger_Condition], [Region_ID], [Faction_ID], [Duration_Hours], [Recurrence], [Reward_Type], [Reward_Value], [Min_Player_Level], [Max_Players], [Lore_Notes]) VALUES (N'EVT011', N'Republic Election Day', N'Story', N'Time-Based', N'Every 4 in-game months', N'REG002', N'FAC002', 48, N'Seasonal', N'XP;Reputation;Lore', NULL, 10, 500, N'Citizens of the Verdant Republic vote on council representatives. Players can campaign for candidates, expose corruption, or manipulate results. Outcome affects Republic questline options for the following season.');
INSERT INTO [Events] ([Event_ID], [Event_Name], [Event_Type], [Trigger_Type], [Trigger_Condition], [Region_ID], [Faction_ID], [Duration_Hours], [Recurrence], [Reward_Type], [Reward_Value], [Min_Player_Level], [Max_Players], [Lore_Notes]) VALUES (N'EVT012', N'Syndicate Purge', N'Faction', N'Faction-Reputation', N'Syndicate rep drops below Hostile', N'REG004', N'FAC003', 12, N'Permanent', N'XP;Reputation', NULL, 1, 10, N'When a player''s Syndicate reputation becomes Hostile, the Syndicate sends escalating waves of enforcers. Surviving the Purge and escaping converts rep to Neutral. Black Jade leads the final wave if rep remains Hostile for 72 hours.');
INSERT INTO [Events] ([Event_ID], [Event_Name], [Event_Type], [Trigger_Type], [Trigger_Condition], [Region_ID], [Faction_ID], [Duration_Hours], [Recurrence], [Reward_Type], [Reward_Value], [Min_Player_Level], [Max_Players], [Lore_Notes]) VALUES (N'EVT013', N'The Undervault Awakening', N'Hidden', N'Player-Action', N'Collect all 8 House Mireth Relics', N'REG010', NULL, 24, N'One-Time', N'XP;Lore;Item', NULL, 30, 3, N'Assembling all Mireth Relics in the Undervault triggers the awakening of an ancient guardian construct. The Archivist appears for the only time in the game as an active NPC. The lore reveal recontextualizes the entire main story.');
INSERT INTO [Events] ([Event_ID], [Event_Name], [Event_Type], [Trigger_Type], [Trigger_Condition], [Region_ID], [Faction_ID], [Duration_Hours], [Recurrence], [Reward_Type], [Reward_Value], [Min_Player_Level], [Max_Players], [Lore_Notes]) VALUES (N'EVT014', N'The Dawnrider Grand Race', N'Faction', N'Time-Based', N'Every 3 in-game weeks', N'REG006', N'FAC008', 24, N'Seasonal', N'XP;Currency;Item', NULL, 8, 32, N'The Dawnrider clan hosts a cross-desert racing event open to all factions. Vehicles, augmented runners, and mounted creatures all compete. Cheating is allowed. Getting caught is not.');
INSERT INTO [Events] ([Event_ID], [Event_Name], [Event_Type], [Trigger_Type], [Trigger_Condition], [Region_ID], [Faction_ID], [Duration_Hours], [Recurrence], [Reward_Type], [Reward_Value], [Min_Player_Level], [Max_Players], [Lore_Notes]) VALUES (N'EVT015', N'Digital Sprawl Surge', N'Dynamic', N'Random', N'Netrunner activity exceeds threshold in REG012', N'REG012', NULL, 4, N'Permanent', N'XP;Item;Lore', NULL, 20, 25, N'When too many Netrunners access the Digital Sprawl simultaneously, the layer destabilizes, creating rare high-value data nodes and corrupted zones with powerful AI defenders. ORACLE-9 briefly becomes fully communicative during surges.');
INSERT INTO [Events] ([Event_ID], [Event_Name], [Event_Type], [Trigger_Type], [Trigger_Condition], [Region_ID], [Faction_ID], [Duration_Hours], [Recurrence], [Reward_Type], [Reward_Value], [Min_Player_Level], [Max_Players], [Lore_Notes]) VALUES (N'EVT016', N'The Ironveil Blockade', N'World', N'Faction-Reputation', N'Ironveil faction rep Hostile OR main questline Chapter 4', N'REG007', N'FAC001', 96, N'One-Time', N'XP;Reputation;Lore', NULL, 22, 200, N'The Ironveil Empire blockades Port Mira''s harbor, demanding the Merchant Guilds cut ties with Republic factions. Players must negotiate, fight through, or smuggle past the blockade. Guild and Empire reputation affected permanently.');
INSERT INTO [Events] ([Event_ID], [Event_Name], [Event_Type], [Trigger_Type], [Trigger_Condition], [Region_ID], [Faction_ID], [Duration_Hours], [Recurrence], [Reward_Type], [Reward_Value], [Min_Player_Level], [Max_Players], [Lore_Notes]) VALUES (N'EVT017', N'The Root Harvest', N'Seasonal', N'Time-Based', N'End of each seasonal cycle', N'REG005', N'FAC004', 48, N'Seasonal', N'Item;Reputation', NULL, 1, 500, N'Root Covenant members gather the season''s harvest of rare botanical resources. Outsiders may help for reputation rewards. Hostile factions that attempt to steal during the Harvest trigger a faction war event chain.');
INSERT INTO [Events] ([Event_ID], [Event_Name], [Event_Type], [Trigger_Type], [Trigger_Condition], [Region_ID], [Faction_ID], [Duration_Hours], [Recurrence], [Reward_Type], [Reward_Value], [Min_Player_Level], [Max_Players], [Lore_Notes]) VALUES (N'EVT018', N'Ghost Hunt', N'Hidden', N'Player-Action', N'EchoID app active + Ghost career or Phantom Bureau rep Friendly+', N'REG002', N'FAC010', 6, N'Permanent', N'XP;Lore;Item', NULL, 18, 1, N'The Phantom Bureau deploys a hidden target in the Citadel. Only players with EchoID active and sufficient rep can detect the target. First player to identify and report them receives full reward. Target identity changes each spawn.');
INSERT INTO [Events] ([Event_ID], [Event_Name], [Event_Type], [Trigger_Type], [Trigger_Condition], [Region_ID], [Faction_ID], [Duration_Hours], [Recurrence], [Reward_Type], [Reward_Value], [Min_Player_Level], [Max_Players], [Lore_Notes]) VALUES (N'EVT019', N'The Merchant Wars Anniversary', N'Seasonal', N'Time-Based', N'Once per annual in-game cycle', N'REG007', N'FAC008', 72, N'Seasonal', N'XP;Currency;Lore', NULL, 5, 1000, N'Port Mira commemorates the end of the Merchant Wars with a festival of trade, combat exhibitions, and historical reenactments. Rare legacy module blueprints become available for the duration.');
INSERT INTO [Events] ([Event_ID], [Event_Name], [Event_Type], [Trigger_Type], [Trigger_Condition], [Region_ID], [Faction_ID], [Duration_Hours], [Recurrence], [Reward_Type], [Reward_Value], [Min_Player_Level], [Max_Players], [Lore_Notes]) VALUES (N'EVT020', N'Void Collapse Warning', N'Story', N'Quest-Chain', N'Complete Void Walker questline Chapter 3 + Sable''s Arc', N'REG008', N'FAC007', 168, N'One-Time', N'XP;Lore;Item', NULL, 35, 10, N'Sable reveals that the Void Rift is expanding faster than anyone has publicly acknowledged. Players must gather representatives from all major factions for an unprecedented cooperation mission. The Miraverse''s future depends on the outcome.');
INSERT INTO [Events] ([Event_ID], [Event_Name], [Event_Type], [Trigger_Type], [Trigger_Condition], [Region_ID], [Faction_ID], [Duration_Hours], [Recurrence], [Reward_Type], [Reward_Value], [Min_Player_Level], [Max_Players], [Lore_Notes]) VALUES (N'EVT021', N'Amber Wastes Scavenger Run', N'World', N'Time-Based', N'Every 2 in-game weeks', N'REG013', N'FAC001', 24, N'Weekly', N'XP;Item;Currency', NULL, 10, 20, N'The Empire briefly lifts access restrictions to the Amber Wastes for sanctioned scavenging. Toxic exposure is still lethal without protection. Players race to collect the most salvage before the gate closes again.');
INSERT INTO [Events] ([Event_ID], [Event_Name], [Event_Type], [Trigger_Type], [Trigger_Condition], [Region_ID], [Faction_ID], [Duration_Hours], [Recurrence], [Reward_Type], [Reward_Value], [Min_Player_Level], [Max_Players], [Lore_Notes]) VALUES (N'EVT022', N'The Floating Isles Drift', N'Dynamic', N'Random', N'Wind pattern change — 15% chance per 12 hours', N'REG014', N'FAC002', 8, N'Permanent', N'XP;Item;Lore', NULL, 15, 30, N'The Floating Isles shift their position relative to the ground regions, occasionally drifting over inaccessible zones and revealing temporary drop points. Sky pirates take advantage. Pathfinder career players get 2-hour advance notice.');
INSERT INTO [Events] ([Event_ID], [Event_Name], [Event_Type], [Trigger_Type], [Trigger_Condition], [Region_ID], [Faction_ID], [Duration_Hours], [Recurrence], [Reward_Type], [Reward_Value], [Min_Player_Level], [Max_Players], [Lore_Notes]) VALUES (N'EVT023', N'The Biolabs Incident', N'Hidden', N'Player-Action', N'Discover Biolabs District + Voss questline Chapter 2', N'REG015', N'FAC005', 18, N'One-Time', N'XP;Lore;Item', NULL, 28, 5, N'A containment failure in the Voss Collective''s deepest lab level releases experimental bio-digital entities. Players must contain the breach before it spreads to the Citadel above. Dr. Voss is directly implicated in the incident.');
INSERT INTO [Events] ([Event_ID], [Event_Name], [Event_Type], [Trigger_Type], [Trigger_Condition], [Region_ID], [Faction_ID], [Duration_Hours], [Recurrence], [Reward_Type], [Reward_Value], [Min_Player_Level], [Max_Players], [Lore_Notes]) VALUES (N'EVT024', N'Ironclaw Championship', N'Faction', N'Time-Based', N'Every 4 in-game weeks', N'REG001', N'FAC011', 72, N'Weekly', N'XP;Item;Reputation', NULL, 10, 16, N'The Ironclaw Brotherhood''s combat excellence tournament. Open to all careers but heavily favors physical combat builds. Kael Ironclaw personally fights the bracket winner — the only reliable way to unlock his personal questline.');
INSERT INTO [Events] ([Event_ID], [Event_Name], [Event_Type], [Trigger_Type], [Trigger_Condition], [Region_ID], [Faction_ID], [Duration_Hours], [Recurrence], [Reward_Type], [Reward_Value], [Min_Player_Level], [Max_Players], [Lore_Notes]) VALUES (N'EVT025', N'The Mirror Coast Salvage Race', N'World', N'Random', N'Shipwreck detection event in REG011', N'REG011', N'FAC008', 12, N'Permanent', N'XP;Currency;Item', NULL, 8, 40, N'When a new shipwreck is detected off the Mirror Coast, factions race to be first to the salvage site. Deepkeel divers have home advantage. Players can hire, sabotage, or race independently to claim the highest-value cargo.');

